export enum SyncMode {
  FREE = 'Free',
  SYNC = 'Sync'
}

export enum TimeDivision {
  T_1_32 = '1/32',
  T_1_16 = '1/16',
  T_1_8 = '1/8',
  T_1_4 = '1/4',
  T_1_2 = '1/2',
  T_1_1 = '1/1'
}

export interface PluginState {
  delayTimeMs: number;
  syncMode: SyncMode;
  timeDivision: TimeDivision;
  feedback: number; // 0-100%
  transpose: number; // -12 to +12
  velocityScale: number; // 0-100%
  chance: number; // 0-100% (Probability of repeat)
  bypass: boolean;
}

export const INITIAL_STATE: PluginState = {
  delayTimeMs: 250,
  syncMode: SyncMode.SYNC,
  timeDivision: TimeDivision.T_1_4,
  feedback: 50,
  transpose: 0,
  velocityScale: 80,
  chance: 100,
  bypass: false
};

import React from 'react';

export const COLORS = {
  accent: '#38bdf8', // Light Blue
  bgDark: '#0f172a',
  bgPanel: '#1e293b',
  textMuted: '#94a3b8',
  textActive: '#f8fafc',
  danger: '#ef4444'
};

export const UI_DIMENSIONS = {
  knobSize: 80,
  panelPadding: '1.5rem',
  borderRadius: '0.75rem'
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { COLORS } from '../constants';

interface KnobProps {
  label: string;
  value: number;
  min: number;
  max: number;
  suffix?: string;
  step?: number;
  onChange: (val: number) => void;
}

export const Knob: React.FC<KnobProps> = ({ label, value, min, max, suffix = '', step = 1, onChange }) => {
  const [isDragging, setIsDragging] = useState(false);
  const startY = useRef(0);
  const startValue = useRef(0);

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    startY.current = e.clientY;
    startValue.current = value;
    document.body.style.cursor = 'ns-resize';
  };

  const handleMouseMove = useCallback((e: MouseEvent) => {
    if (!isDragging) return;
    const delta = startY.current - e.clientY;
    const range = max - min;
    const sensitivity = 0.5; // Pixels per unit
    const newValue = Math.min(max, Math.max(min, startValue.current + (delta * (range / 200) * sensitivity)));
    onChange(Math.round(newValue / step) * step);
  }, [isDragging, max, min, onChange, step]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
    document.body.style.cursor = 'default';
  }, []);

  useEffect(() => {
    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  const percentage = (value - min) / (max - min);
  const rotation = -135 + (percentage * 270);

  return (
    <div className="flex flex-col items-center select-none group">
      <div 
        className="relative w-16 h-16 cursor-ns-resize mb-2"
        onMouseDown={handleMouseDown}
      >
        {/* Outer Ring */}
        <svg viewBox="0 0 100 100" className="w-full h-full">
          <circle 
            cx="50" cy="50" r="40" 
            fill="none" 
            stroke="#334155" 
            strokeWidth="8"
            strokeDasharray="188"
            strokeDashoffset="0"
            strokeLinecap="round"
            style={{ transform: 'rotate(135deg)', transformOrigin: 'center' }}
          />
          <circle 
            cx="50" cy="50" r="40" 
            fill="none" 
            stroke={COLORS.accent} 
            strokeWidth="8"
            strokeDasharray="188"
            strokeDashoffset={188 - (percentage * 141)} // 141 is roughly 270 degrees of 188 circum
            strokeLinecap="round"
            style={{ 
              transform: 'rotate(135deg)', 
              transformOrigin: 'center',
              transition: isDragging ? 'none' : 'stroke-dashoffset 0.1s ease-out'
            }}
          />
        </svg>

        {/* Pointer Indicator */}
        <div 
          className="absolute inset-0 flex items-center justify-center"
          style={{ transform: `rotate(${rotation}deg)` }}
        >
          <div className="w-1.5 h-4 bg-slate-100 rounded-full mb-8 shadow-sm"></div>
        </div>

        {/* Center Label */}
        <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
          <span className="text-[10px] font-bold text-slate-400">
            {Math.round(value)}{suffix}
          </span>
        </div>
      </div>
      <label className="text-[11px] uppercase tracking-wider font-semibold text-slate-500 group-hover:text-slate-300 transition-colors">
        {label}
      </label>
    </div>
  );
};

import React from 'react';
import { COLORS } from '../constants';

interface ToggleProps {
  label: string;
  active: boolean;
  onToggle: () => void;
  activeColor?: string;
}

export const ToggleSwitch: React.FC<ToggleProps> = ({ label, active, onToggle, activeColor = COLORS.accent }) => {
