import React from 'react';
import { PluginState, SyncMode } from '../types';
import { COLORS } from '../constants';

export const Visualizer: React.FC<{ state: PluginState }> = ({ state }) => {
  // Mock taps for visualization
  const tapCount = Math.floor(state.feedback / 10) + 1;
  const taps = Array.from({ length: Math.min(8, tapCount) }, (_, i) => {
    const scale = Math.pow(state.velocityScale / 100, i);
    const pos = (i + 1) * (state.delayTimeMs / 20);
    return { scale, pos, note: 60 + (i * state.transpose) };
  });

  return (
    <div className="w-full h-24 bg-slate-900 rounded-xl overflow-hidden relative border border-slate-800 flex items-end px-4 pb-4">
      {/* Grid Lines */}
      <div className="absolute inset-0 grid grid-cols-8 gap-0 opacity-10">
        {[...Array(8)].map((_, i) => (
          <div key={i} className="border-r border-slate-500 h-full"></div>
        ))}
      </div>

      <div className="relative flex items-end gap-2 h-full w-full">
        {/* Source Note */}
        <div 
          className="w-2 rounded-t-sm" 
          style={{ height: '80%', backgroundColor: COLORS.accent, boxShadow: `0 0 10px ${COLORS.accent}44` }}
        ></div>

        {/* Delay Taps */}
        {taps.map((tap, i) => (
          <div 
            key={i}
            className="w-2 rounded-t-sm transition-all duration-300"
            style={{ 
              height: `${80 * tap.scale}%`, 
              backgroundColor: '#475569',
              opacity: state.bypass ? 0.1 : 0.8
            }}
          ></div>
        ))}
      </div>

      <div className="absolute top-2 right-3 text-[9px] uppercase font-bold text-slate-600 tracking-tighter">
        Real-time Output Preview
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { PluginState, SyncMode, TimeDivision } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const PLUGIN_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    delayTimeMs: { type: Type.NUMBER },
    feedback: { type: Type.NUMBER },
    transpose: { type: Type.NUMBER },
    velocityScale: { type: Type.NUMBER },
    chance: { type: Type.NUMBER },
    syncMode: { type: Type.STRING },
    timeDivision: { type: Type.STRING },
    description: { type: Type.STRING }
  },
  required: ["delayTimeMs", "feedback", "transpose", "velocityScale", "chance", "syncMode", "timeDivision", "description"]
};

export async function getAIPreset(mood: string): Promise<{ state: Partial<PluginState>, description: string }> {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate a MIDI Delay preset for a ${mood} mood. 
      MIDI Delay Parameters: 
      - feedback (0-100)
      - transpose (-12 to +12)
      - velocityScale (0-100)
      - chance (0-100)
      - syncMode ('Free' or 'Sync')
      - timeDivision ('1/32', '1/16', '1/8', '1/4', '1/2', '1/1')
      - delayTimeMs (10 to 2000)
      Return valid JSON.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: PLUGIN_SCHEMA
      }
    });

    const data = JSON.parse(response.text);
    return {
      state: {
        delayTimeMs: data.delayTimeMs,
        feedback: data.feedback,
        transpose: data.transpose,
        velocityScale: data.velocityScale,
        chance: data.chance,
        syncMode: data.syncMode as SyncMode,
        timeDivision: data.timeDivision as TimeDivision,
      },
      description: data.description
    };
  } catch (error) {
    console.error("AI Preset failed", error);
    throw error;
  }
}

import React, { useState, useCallback } from 'react';
