export type DelayMode = 'ms' | 'sync';

export type Step = {
  pitch: number;        // -24 to 24
  velocity: number;     // 1 to 127
  modwheel: number;     // 0 to 127
  probability: number;  // 0 to 100
  muted: boolean;
};

export type PluginState = {
  delayMode: DelayMode;
  delayTimeMs: number;
  syncDivision: string;
  stepCount: number;    // 1 to 16
  steps: Step[];
};

export const INITIAL_STATE: PluginState = {
  delayMode: 'sync',
  delayTimeMs: 500,
  syncDivision: '1/4',
  stepCount: 16,
  steps: Array.from({ length: 16 }, () => ({
    pitch: 0,
    velocity: 100,
    modwheel: 0,
    probability: 100,
    muted: false,
  })),
};

import React, { useRef, useCallback } from 'react';
import { Step } from '../types';

interface StepLaneProps {
  label: string;
  property: keyof Step;
  steps: Step[];
  stepCount: number;
  min: number;
  max: number;
  isBipolar?: boolean;
  onUpdate: (index: number, value: number | boolean) => void;
}

export const StepLane: React.FC<StepLaneProps> = ({ 
  label, property, steps, stepCount, min, max, isBipolar, onUpdate 
}) => {
  const laneRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);

  const calculateValue = useCallback((clientY: number) => {
    if (!laneRef.current) return 0;
    const rect = laneRef.current.getBoundingClientRect();
    const height = rect.height;
    const relativeY = Math.max(0, Math.min(height, clientY - rect.top));
    const normalized = 1 - (relativeY / height); // 0 at bottom, 1 at top

    return Math.round(min + (normalized * (max - min)));
  }, [min, max]);

  const handleInteraction = (e: React.MouseEvent | React.TouchEvent, index: number) => {
    if (property === 'muted') {
      if ('button' in e && e.type === 'mousedown') {
        onUpdate(index, !steps[index].muted);
      }
      return;
    }

    const clientY = 'touches' in e ? e.touches[0].clientY : e.clientY;
    onUpdate(index, calculateValue(clientY));
  };

  const onMouseDown = (e: React.MouseEvent, index: number) => {
    isDragging.current = true;
    handleInteraction(e, index);
  };

  const onMouseEnter = (e: React.MouseEvent, index: number) => {
    if (isDragging.current) {
      handleInteraction(e, index);
    }
  };

  const onMouseUpGlobal = useCallback(() => {
    isDragging.current = false;
  }, []);

  React.useEffect(() => {
    window.addEventListener('mouseup', onMouseUpGlobal);
    return () => window.removeEventListener('mouseup', onMouseUpGlobal);
  }, [onMouseUpGlobal]);

  return (
    <div className="flex flex-col gap-1">
      <div className="flex justify-between items-end px-1">
        <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">{label}</span>
        <span className="text-[9px] opacity-40">[{min}...{max}]</span>
      </div>

      <div 
        ref={laneRef}
        className="h-20 bg-[#1a1a1a] border border-[#333] flex items-stretch gap-[1px] p-[2px] relative overflow-hidden"
      >
        {/* Zero line for bipolar */}
        {isBipolar && (
          <div className="absolute left-0 right-0 top-1/2 h-[1px] bg-green-500/20 pointer-events-none"></div>
        )}

        {steps.map((step, i) => {
          const val = step[property] as number | boolean;
          const isMuted = step.muted || i >= stepCount;

          if (property === 'muted') {
            const isInactive = step.muted || i >= stepCount;
            return (
              <button
                key={i}
                onMouseDown={(e) => onMouseDown(e, i)}
                className={`flex-1 border transition-colors ${isInactive ? 'bg-transparent border-green-900/30 text-green-900/30' : 'bg-[#00ff41] border-[#00ff41] text-black'}`}
              >
                <div className="h-full w-full flex items-center justify-center text-[8px] font-black">
                  {!isInactive && "ON"}
                </div>
              </button>
            );
          }

          const numVal = val as number;
          const heightPercent = ((numVal - min) / (max - min)) * 100;

          return (
            <div
              key={i}
              onMouseDown={(e) => onMouseDown(e, i)}
              onMouseEnter={(e) => onMouseEnter(e, i)}
              className={`flex-1 relative cursor-crosshair group ${isMuted ? 'opacity-10' : 'opacity-100'}`}
            >
              <div className="absolute inset-0 bg-green-500/5 group-hover:bg-green-500/10"></div>

              {isBipolar ? (
                <div 
                  className="absolute left-[10%] right-[10%] bg-[#00ff41] shadow-[0_0_8px_#00ff4155]"
                  style={{ 
                    top: numVal >= 0 ? '50%' : `${50 - (Math.abs(numVal)/max * 50)}%`,
                    bottom: numVal >= 0 ? `${50 - (Math.abs(numVal)/max * 50)}%` : '50%',
                    transform: numVal >= 0 ? 'translateY(-100%)' : 'translateY(100%)'
                  }}
                ></div>
              ) : (
                <div 
                  className="absolute bottom-0 left-[10%] right-[10%] bg-[#00ff41] shadow-[0_0_8px_#00ff4155]"
                  style={{ height: `${heightPercent}%` }}
                ></div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

