import React, { useRef, useCallback, useEffect } from 'react';
import { Step } from '../types';

interface StepLaneProps {
  label: string;
  property: keyof Step;
  steps: Step[];
  stepCount: number;
  min: number;
  max: number;
  isBipolar?: boolean;
  onUpdate: (index: number, value: number | boolean) => void;
  onRandomize: () => void;
}

const LABEL_HEIGHT = 24;

const DiceIcon = () => (
  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className="opacity-80">
    <rect x="3" y="3" width="18" height="18" rx="2" ry="2" />
    <circle cx="8.5" cy="8.5" r="1.5" fill="currentColor" />
    <circle cx="15.5" cy="15.5" r="1.5" fill="currentColor" />
    <circle cx="12" cy="12" r="1.5" fill="currentColor" />
  </svg>
);

export const StepLane: React.FC<StepLaneProps> = ({ 
  label, property, steps, stepCount, min, max, isBipolar, onUpdate, onRandomize 
}) => {
  const laneRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);

  const calculateValue = useCallback((clientY: number) => {
    if (!laneRef.current) return 0;
    const rect = laneRef.current.getBoundingClientRect();
    const barAreaHeight = rect.height - LABEL_HEIGHT;
    const relativeY = Math.max(0, Math.min(barAreaHeight, clientY - rect.top));
    const normalized = 1 - (relativeY / barAreaHeight);
    return Math.round(min + (normalized * (max - min)));
  }, [min, max]);

  const updateFromMouseEvent = useCallback((e: MouseEvent | React.MouseEvent) => {
    if (!laneRef.current) return;
    const rect = laneRef.current.getBoundingClientRect();
    const relativeX = e.clientX - rect.left;
    const stepWidth = rect.width / 16;
    const index = Math.max(0, Math.min(15, Math.floor(relativeX / stepWidth)));

    if (property === 'muted') return;

    const value = calculateValue(e.clientY);
    onUpdate(index, value);
  }, [calculateValue, onUpdate, property]);

  const onMouseDown = (e: React.MouseEvent, index: number) => {
    isDragging.current = true;
    if (property === 'muted') {
      onUpdate(index, !steps[index].muted);
    } else {
      updateFromMouseEvent(e);
    }
  };

  useEffect(() => {
    const handleGlobalMouseMove = (e: MouseEvent) => {
      if (isDragging.current) updateFromMouseEvent(e);
    };
    const handleGlobalMouseUp = () => {
      isDragging.current = false;
    };
    window.addEventListener('mousemove', handleGlobalMouseMove);
    window.addEventListener('mouseup', handleGlobalMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleGlobalMouseMove);
      window.removeEventListener('mouseup', handleGlobalMouseUp);
    };
  }, [updateFromMouseEvent]);

  const formatValue = (val: number | boolean) => {
    if (typeof val === 'boolean') return val ? 'OFF' : 'ON';
    if (property === 'probability') return `${val}%`;
    if (property === 'pitch' && val > 0) return `+${val}`;
    return val.toString();
  };

  return (
    <div className="flex flex-col gap-1">
      <div className="flex justify-between items-end px-1 mb-1">
        <div className="flex items-center gap-2">
          <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">{label}</span>
          <button 
            onClick={(e) => { e.stopPropagation(); onRandomize(); }}
            className="hover:text-white transition-colors p-0.5 border border-transparent hover:border-green-500/30 rounded active:scale-90"
            title="Randomize Lane"
          >
            <DiceIcon />
          </button>
        </div>
        <span className="text-[9px] opacity-40">[{min}...{max}]</span>
      </div>

      <div 
        ref={laneRef}
        className="h-28 bg-[#1a1a1a] border border-[#333] flex items-stretch gap-[1px] p-[2px] relative overflow-hidden"
      >
        {isBipolar && (
          <div 
            className="absolute left-0 right-0 h-[1px] bg-green-500/20 pointer-events-none"
            style={{ top: `calc(50% - ${LABEL_HEIGHT / 2}px)` }}
          ></div>
        )}

        {steps.map((step, i) => {
          const val = step[property];
          const isMuted = step.muted || i >= stepCount;

          return (
            <div
              key={i}
              onMouseDown={(e) => onMouseDown(e, i)}
              className={`flex-1 flex flex-col relative cursor-crosshair group ${isMuted ? 'opacity-10' : 'opacity-100'}`}
            >
              <div className="flex-1 relative">
                <div className="absolute inset-0 bg-green-500/5 group-hover:bg-green-500/10"></div>
                {property === 'muted' ? (
                   <div className={`absolute inset-1 border transition-colors flex items-center justify-center ${step.muted ? 'bg-transparent border-green-900/30' : 'bg-[#00ff41] border-[#00ff41]'}`}>
                      {!step.muted && <div className="w-1.5 h-1.5 bg-black rounded-full shadow-[0_0_4px_#000]"></div>}
                   </div>
                ) : isBipolar ? (
                  <div 
                    className="absolute left-[10%] right-[10%] bg-[#00ff41] shadow-[0_0_8px_#00ff4155] pointer-events-none"
                    style={{ 
                      top: (val as number) >= 0 ? '50%' : `${50 - (Math.abs(val as number)/max * 50)}%`,
                      bottom: (val as number) >= 0 ? `${50 - (Math.abs(val as number)/max * 50)}%` : '50%',
                      transform: (val as number) >= 0 ? 'translateY(-100%)' : 'translateY(100%)'
                    }}
                  ></div>
                ) : (
                  <div 
                    className="absolute bottom-0 left-[10%] right-[10%] bg-[#00ff41] shadow-[0_0_8px_#00ff4155] pointer-events-none"
                    style={{ height: `${((val as number - min) / (max - min)) * 100}%` }}
                  ></div>
                )}
              </div>
              <div 
                className="flex items-center justify-center text-[12px] font-black text-[#00ff41]/90 select-none pointer-events-none"
                style={{ height: `${LABEL_HEIGHT}px` }}
              >
                {formatValue(val)}
              </div>
