// C++ Code Templates
const processorH = `// PluginProcessor.h
#pragma once
#include <JuceHeader.h>

struct DelayStep {
    int pitchOffset = 0;
    uint8 velocity = 100;
    float probability = 1.0f;
    bool muted = false;
};

class AetherProcessor : public juce::AudioProcessor {
public:
    AetherProcessor();
    void prepareToPlay (double sampleRate, int samplesPerBlock) override;
    void processBlock (juce::AudioBuffer<float>&, juce::MidiBuffer&) override;

    // MIDI Delay Logic
    void handleMidiEvent(const juce::MidiMessage& m, int sampleOffset);

    juce::AudioProcessorEditor* createEditor() override;
    bool hasEditor() const override { return true; }

    // State
    std::array<DelayStep, 16> steps;
    int activeStepCount = 16;
    double currentDelayMs = 500.0;
    juce::String currentSync = "1/4";

private:
    double lastSampleRate = 44100.0;
    juce::MidiBuffer delayBuffer;
    JUCE_DECLARE_NON_COPYABLE_WITH_LEAK_DETECTOR (AetherProcessor)
};`;

const processorCpp = `// PluginProcessor.cpp
#include "PluginProcessor.h"
#include "PluginEditor.h"

AetherProcessor::AetherProcessor() : AudioProcessor(...) {
    // Initialize parameters here
}

void AetherProcessor::prepareToPlay (double sampleRate, int samplesPerBlock) {
    lastSampleRate = sampleRate;
    delayBuffer.clear();
}

void AetherProcessor::processBlock (juce::AudioBuffer<float>& buffer, juce::MidiBuffer& midiMessages) {
    // Process incoming MIDI to delay buffer
    for (const auto metadata : midiMessages) {
        auto msg = metadata.getMessage();
        int offset = metadata.samplePosition;

        if (msg.isNoteOn()) {
            for (int i = 0; i < activeStepCount; ++i) {
                if (steps[i].muted) continue;

                auto delayedMsg = msg;
                delayedMsg.setNoteNumber(msg.getNoteNumber() + steps[i].pitchOffset);
                delayedMsg.setVelocity(steps[i].velocity / 127.0f);

                double delayInSamples = (currentDelayMs * 0.001) * lastSampleRate * (i + 1);
                delayBuffer.addEvent(delayedMsg, offset + (int)delayInSamples);
            }
        }
    }

    // Pull from delay buffer
    midiMessages.addEvents(delayBuffer, 0, buffer.getNumSamples(), 0);
    delayBuffer.clear(0, buffer.getNumSamples());
}

juce::AudioProcessorEditor* AetherProcessor::createEditor() {
    return new AetherEditor(*this);
}`;

const editorH = `// PluginEditor.h
