    stepCountSlider.onValueChange = [this] { audioProcessor.activeStepCount = (int)stepCountSlider.getValue(); };
    addAndMakeVisible(stepCountSlider);

    // Reduced height to end exactly under the step count slider.
    // Slider bottom is at 970. Setting window height to 980 for a clean fit.
    setSize (1100, 980); 
    startTimerHz(30);
}

