    stepCountSlider.onValueChange = [this] { audioProcessor.activeStepCount = (int)stepCountSlider.getValue(); };
    addAndMakeVisible(stepCountSlider);

    // Height calculation:
    // Header finishes at ~180.
    // 5 lanes * 150 = 750.
    // 180 + 750 = 930 is start of slider area.
    // Label area = 915.
    // Slider y = 935, height = 35. Bottom = 970.
    // Setting total window height to exactly 970 to end right under the slider.
    setSize (1100, 970); 
    startTimerHz(30);
}

