public:
    AetherLookAndFeel() {
        setColour(juce::ResizableWindow::backgroundColourId, juce::Colour(0xFF121212));
        setColour(juce::ComboBox::backgroundColourId, juce::Colour(0xFF121212));
        setColour(juce::ComboBox::outlineColourId, juce::Colour(0xFF00FF41));
        setColour(juce::ComboBox::textColourId, juce::Colour(0xFF00FF41));
        setColour(juce::Slider::thumbColourId, juce::Colour(0xFF00FF41));
        setColour(juce::Slider::trackColourId, juce::Colour(0xFF2A2A2A));
    }

    void drawRotarySlider (juce::Graphics& g, int x, int y, int width, int height,
                          float sliderPos, const float rotaryStartAngle, const float rotaryEndAngle,
                          juce::Slider& slider) override {
        auto radius = (float) juce::jmin (width / 2, height / 2) - 4.0f;
        auto centreX = (float) x + (float) width * 0.5f;
        auto centreY = (float) y + (float) height * 0.5f;
        auto rx = centreX - radius;
        auto ry = centreY - radius;
        auto rw = radius * 2.0f;
        auto angle = rotaryStartAngle + sliderPos * (rotaryEndAngle - rotaryStartAngle);

        g.setColour (juce::Colour(0xFF1A1A1A));
        g.fillEllipse (rx, ry, rw, rw);
        g.setColour (juce::Colour(0xFF00FF41).withAlpha(0.2f));
        g.drawEllipse (rx, ry, rw, rw, 1.0f);

        juce::Path p;
        auto pointerLength = radius * 0.8f;
        auto pointerThickness = 3.0f;
        p.addRectangle (-pointerThickness * 0.5f, -radius, pointerThickness, pointerLength);
        p.applyTransform (juce::AffineTransform::rotation (angle).translated (centreX, centreY));
        g.setColour (juce::Colour(0xFF00FF41));
        g.fillPath (p);
    }
};

