#include "PluginProcessor.h"
#include "PluginEditor.h"

AetherAudioProcessorEditor::AetherAudioProcessorEditor (AetherAudioProcessor& p)
    : AudioProcessorEditor (&p), audioProcessor (p)
{
    setLookAndFeel(&lookAndFeel);

    syncMenu.addItem("ms", 1);
    syncMenu.addItem("1/1", 2);
    syncMenu.addItem("1/2", 3);
    syncMenu.addItem("1/4", 4);
    syncMenu.addItem("1/8", 5);
    syncMenu.addItem("1/16", 6);
    syncMenu.onChange = [this] { audioProcessor.syncDivisionIndex = syncMenu.getSelectedItemIndex(); };
    syncMenu.setSelectedItemIndex(audioProcessor.syncDivisionIndex);
    addAndMakeVisible(syncMenu);

    timeSlider.setSliderStyle(juce::Slider::RotaryVerticalDrag);
    timeSlider.setRange(1.0, 2000.0, 1.0);
    timeSlider.setTextBoxStyle(juce::Slider::NoTextBox, false, 0, 0);
    timeSlider.onValueChange = [this] { audioProcessor.delayTimeMs = timeSlider.getValue(); };
    addAndMakeVisible(timeSlider);

    stepCountSlider.setRange(1, 16, 1);
    stepCountSlider.setSliderStyle(juce::Slider::LinearBar);
    stepCountSlider.onValueChange = [this] { audioProcessor.activeStepCount = (int)stepCountSlider.getValue(); };
    addAndMakeVisible(stepCountSlider);

    // Ultra Compact Window Size
    // Fits exactly under the Step Count slider (Y ~ 740)
    setSize (1100, 740); 
    startTimerHz(30);
}

AetherAudioProcessorEditor::~AetherAudioProcessorEditor() {
    setLookAndFeel(nullptr);
}

void AetherAudioProcessorEditor::timerCallback() {
    timeSlider.setVisible(audioProcessor.syncDivisionIndex == 0);
}

void AetherAudioProcessorEditor::paint (juce::Graphics& g) {
    g.fillAll (getLookAndFeel().findColour (juce::ResizableWindow::backgroundColourId));

    g.setColour (juce::Colour(0xFF00FF41));
    g.setFont (juce::Font ("IBM Plex Mono", 60.0f, juce::Font::bold));
    g.drawText ("AETHER", 40, 40, 400, 60, juce::Justification::left);

    g.setFont (14.0f);
    g.setOpacity(0.6f);
    g.drawText ("Polyphonic MIDI Delay by darkInteger", 45, 100, 400, 20, juce::Justification::left);

    int laneY = 160;
    for (auto& lane : lanes) {
        g.setOpacity(0.7f);
        g.drawText(lane.label.toUpperCase(), 40, laneY - 25, 200, 20, juce::Justification::left);

        g.setColour(juce::Colour(0xFF333333));
        g.drawRect(40, laneY, 1020, 80, 1);

        float stepW = 1020.0f / 16.0f;
        for (int i = 0; i < 16; ++i) {
            g.setColour(juce::Colour(0xFF2A2A2A));
            g.fillRect(40.0f + i * stepW + 2, (float)laneY + 2, stepW - 4, 76.0f);

            if (i < audioProcessor.activeStepCount) {
                g.setColour(juce::Colour(0xFF00FF41));
                // Rendering Logic
            }
        }
        laneY += 110;
    }

    g.setColour(juce::Colour(0xFF00FF41));
    g.setFont(10.0f);
    g.drawText("STEP COUNT", 40, 680, 200, 15, juce::Justification::left);
}

void AetherAudioProcessorEditor::resized() {
    syncMenu.setBounds(850, 60, 150, 30);
    timeSlider.setBounds(750, 45, 80, 80);

    // Positioned snugly at the bottom
    stepCountSlider.setBounds(40, 700, 1020, 30);
}`;

