void AetherAudioProcessorEditor::handleLaneInteraction(const juce::MouseEvent& e) {
    int laneY = 160;
    for (int l = 0; l < lanes.size(); ++l) {
        juce::Rectangle<int> laneArea(40, laneY, 1020, 80);
