void AetherAudioProcessorEditor::paint (juce::Graphics& g) {
    g.fillAll (juce::Colour(0xFF121212));

    // Header
    g.setColour (juce::Colour(0xFF00FF41));
    g.setFont (juce::Font ("IBM Plex Mono", 60.0f, juce::Font::bold));
    g.drawText ("AETHER", 40, 40, 400, 60, juce::Justification::left);

    g.setFont (14.0f);
    g.setOpacity(0.6f);
    g.drawText ("Polyphonic MIDI Delay", 45, 100, 400, 20, juce::Justification::left);
    g.drawText ("by darkInteger", 45, 120, 400, 20, juce::Justification::left);

    int laneY = 160;
    for (int l = 0; l < lanes.size(); ++l) {
        auto& lane = lanes[l];
        g.setOpacity(0.7f);
        g.setFont (juce::Font ("IBM Plex Mono", 16.0f, juce::Font::bold));
        g.drawText(lane.label.toUpperCase(), 40, laneY - 25, 200, 20, juce::Justification::left);

        float stepW = 1020.0f / 16.0f;
        int barHeight = 56; // Leave room for value label at bottom

        for (int i = 0; i < 16; ++i) {
            auto& step = audioProcessor.steps[i];
            bool isMuted = step.muted || i >= audioProcessor.activeStepCount;
            float opacity = isMuted ? 0.2f : 1.0f;

            juce::Rectangle<float> stepRect(40.0f + i * stepW + 2, (float)laneY, stepW - 4, 80.0f);

            // Background Track
            g.setColour(juce::Colour(0xFF2A2A2A));
            g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY, stepW * 0.8f, (float)barHeight);

            g.setColour(juce::Colour(0xFF00FF41).withAlpha(opacity));

            // Value Logic
            int val = 0;
            juce::String valStr = "";
            if (lane.propertyId == "pitch") { val = step.pitchOffset; valStr = (val > 0 ? "+" : "") + juce::String(val); }
            else if (lane.propertyId == "velocity") { val = step.velocity; valStr = juce::String(val); }
            else if (lane.propertyId == "modwheel") { val = step.modwheel; valStr = juce::String(val); }
            else if (lane.propertyId == "probability") { val = step.probability; valStr = juce::String(val) + "%"; }
            else if (lane.propertyId == "muted") { val = step.muted ? 0 : 1; valStr = step.muted ? "OFF" : "ON"; }

            // Draw Bar
            if (lane.propertyId == "muted") {
                juce::Rectangle<float> muteBox(40.0f + i * stepW + 8, (float)laneY + 8, stepW - 16, barHeight - 16);
                if (!step.muted) {
                    g.fillRect(muteBox);
                    g.setColour(juce::Colour(0xFF000000));
                    g.fillEllipse(muteBox.getCentreX()-3, muteBox.getCentreY()-3, 6, 6);
                } else {
                    g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.1f * opacity));
                    g.drawRect(muteBox, 1.0f);
                }
            } else if (lane.isBipolar) {
                float halfH = barHeight / 2.0f;
                float normVal = (float)val / (float)lane.max;
                float h = std::abs(normVal) * halfH;
                if (val >= 0) g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY + halfH - h, stepW * 0.8f, h);
                else g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY + halfH, stepW * 0.8f, h);

                // Center Line
                g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.2f));
                g.drawHorizontalLine(laneY + halfH, 40.0f + i * stepW, 40.0f + (i + 1) * stepW);
            } else {
                float normVal = (float)(val - lane.min) / (float)(lane.max - lane.min);
                float h = normVal * barHeight;
                g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY + (barHeight - h), stepW * 0.8f, h);
            }

            // Value Label
            g.setColour(juce::Colour(0xFF00FF41).withAlpha(opacity * 0.9f));
            g.setFont(11.0f);
            g.drawText(valStr, 40.0f + i * stepW, laneY + barHeight + 2, stepW, 20, juce::Justification::centred);
        }
        laneY += 110;
    }

    // Step Count Custom Paint
    g.setColour(juce::Colour(0xFF00FF41));
    g.setFont(juce::Font ("IBM Plex Mono", 10.0f, juce::Font::bold));
    g.drawText("STEP COUNT", 40, 680, 200, 15, juce::Justification::left);
    g.drawText(juce::String(audioProcessor.activeStepCount) + " STEPS", 900, 680, 160, 15, juce::Justification::right);
}

