void AetherAudioProcessorEditor::handleLaneInteraction(const juce::MouseEvent& e) {
    int laneY = 160;
    for (int l = 0; l < (int)lanes.size(); ++l) {
        // Area includes bar and text label space
        juce::Rectangle<int> laneArea(40, laneY, 1020, 112);
        if (laneArea.contains(e.x, e.y)) {
            float stepW = 1020.0f / 16.0f;
            int stepIdx = (int)((e.x - 40) / stepW);
            stepIdx = juce::jlimit(0, 15, stepIdx);

            auto& step = audioProcessor.steps[stepIdx];
            auto& lane = lanes[l];

            if (lane.propertyId == "muted") {
                if (e.eventTime == e.mouseDownTime) 
                    step.muted = !step.muted;
            } else {
                // Calculation relative to bar area only (88px)
                float barTop = (float)laneY;
                float normY = 1.0f - (float)(e.y - barTop) / 88.0f;
                normY = juce::jlimit(0.0f, 1.0f, normY);
                int val = (int)(lane.min + normY * (lane.max - lane.min));
                val = juce::jlimit(lane.min, lane.max, val);

                if (lane.propertyId == "pitch") step.pitchOffset = val;
                else if (lane.propertyId == "velocity") step.velocity = val;
                else if (lane.propertyId == "modwheel") step.modwheel = val;
                else if (lane.propertyId == "probability") step.probability = val;
            }
            repaint();
            return;
        }
        laneY += 110;
    }

    // Step Count Area Interaction
    juce::Rectangle<int> stepCountArea(40, 700, 1020, 30);
    if (stepCountArea.contains(e.x, e.y)) {
        float normX = (float)(e.x - 40) / 1020.0f;
        int count = juce::jlimit(1, 16, (int)std::ceil(normX * 16.0f));
        audioProcessor.activeStepCount = count;
        stepCountSlider.setValue(count, juce::dontSendNotification);
        repaint();
    }
}

void AetherAudioProcessorEditor::mouseDown (const juce::MouseEvent& e) { handleLaneInteraction(e); }
void AetherAudioProcessorEditor::mouseDrag (const juce::MouseEvent& e) { handleLaneInteraction(e); }

void AetherAudioProcessorEditor::paint (juce::Graphics& g) {
    g.fillAll (juce::Colour(0xFF121212));

    // Header - CRT GLOW STYLE
    g.setColour (juce::Colour(0xFF00FF41));
    g.setFont (juce::Font ("IBM Plex Mono", 60.0f, juce::Font::bold));
    g.drawText ("AETHER", 40, 40, 400, 60, juce::Justification::left);

    g.setFont (14.0f);
    g.setOpacity(0.6f);
    g.drawText ("Polyphonic MIDI Delay", 45, 100, 400, 20, juce::Justification::left);
    g.drawText ("by darkInteger", 45, 120, 400, 20, juce::Justification::left);

    int laneY = 160;
    for (int l = 0; l < (int)lanes.size(); ++l) {
        auto& lane = lanes[l];
        g.setOpacity(0.7f);
        g.setFont (juce::Font ("IBM Plex Mono", 16.0f, juce::Font::bold));
        g.drawText(lane.label.toUpperCase(), 40, laneY - 25, 200, 20, juce::Justification::left);

        float stepW = 1020.0f / 16.0f;
        int barAreaH = 88; // Match React's h-28 minus label space

        for (int i = 0; i < 16; ++i) {
            auto& step = audioProcessor.steps[i];
            bool isInactive = i >= audioProcessor.activeStepCount;
            float opacity = isInactive ? 0.2f : 1.0f;

            // Background track block (#2A2A2A)
            g.setColour(juce::Colour(0xFF2A2A2A));
            g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY, stepW * 0.8f, (float)barAreaH);

            g.setColour(juce::Colour(0xFF00FF41).withAlpha(opacity));

            int val = 0;
            juce::String valStr = "";
            if (lane.propertyId == "pitch") { val = step.pitchOffset; valStr = (val > 0 ? "+" : "") + juce::String(val); }
            else if (lane.propertyId == "velocity") { val = step.velocity; valStr = juce::String(val); }
            else if (lane.propertyId == "modwheel") { val = step.modwheel; valStr = juce::String(val); }
            else if (lane.propertyId == "probability") { val = step.probability; valStr = juce::String(val) + "%"; }
            else if (lane.propertyId == "muted") { valStr = step.muted ? "OFF" : "ON"; }

            // DRAW BARS (PIXEL-PERFECT REACT MATCHING)
            if (lane.propertyId == "muted") {
                juce::Rectangle<float> muteBox(40.0f + i * stepW + 8, (float)laneY + 8, stepW - 16, (float)barAreaH - 16);
                if (!step.muted) {
                    g.fillRect(muteBox);
                    g.setColour(juce::Colour(0xFF000000));
                    g.fillEllipse(muteBox.getCentreX()-3, muteBox.getCentreY()-3, 6, 6);
                } else {
                    g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.1f * opacity));
                    g.drawRect(muteBox, 1.0f);
                }
            } else if (lane.isBipolar) {
                float halfH = barAreaH / 2.0f;
                float normVal = (float)val / (float)lane.max;
                float h = std::abs(normVal) * halfH;
                if (val >= 0) g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY + halfH - h, stepW * 0.8f, h);
                else g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY + halfH, stepW * 0.8f, h);

                // Bipolar center line (matching React green-500/20)
                g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.2f * opacity));
                g.drawHorizontalLine(laneY + (int)halfH, (int)(40.0f + i * stepW), (int)(40.0f + (i + 1) * stepW));
            } else {
                float normVal = (float)(val - lane.min) / (float)(lane.max - lane.min);
                float h = normVal * barAreaH;
                g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY + (barAreaH - h), stepW * 0.8f, h);
            }

            // VALUE TEXT RENDERING (Matching React position in the 24px label area)
            g.setColour(juce::Colour(0xFF00FF41).withAlpha(opacity * 0.9f));
            g.setFont(juce::Font("IBM Plex Mono", 11.0f, juce::Font::bold));
            g.drawText(valStr, (int)(40.0f + i * stepW), laneY + barAreaH + 2, (int)stepW, 20, juce::Justification::centred);
        }
        laneY += 120; // Spacing adjusted for h-28 (112px)
    }

    // SEGMENTED STEP COUNT SLIDER RENDERING
    g.setColour(juce::Colour(0xFF00FF41));
    g.setFont(juce::Font ("IBM Plex Mono", 10.0f, juce::Font::bold));
    g.drawText("STEP COUNT", 40, 680, 200, 15, juce::Justification::left);
    g.drawText(juce::String(audioProcessor.activeStepCount) + " STEPS", 900, 680, 160, 15, juce::Justification::right);

    float segW = 1020.0f / 16.0f;
    for (int i = 0; i < 16; ++i) {
        juce::Rectangle<float> seg(40.0f + i * segW + 1, 700, segW - 2, 30);
        if (i < audioProcessor.activeStepCount) {
            g.setColour(juce::Colour(0xFF00FF41));
            g.fillRect(seg);
            // Segments inner glow emulation
            g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.2f));
            g.drawRect(seg.expanded(1.0f), 1.0f);
        } else {
            g.setColour(juce::Colour(0xFF1A1A1A));
            g.fillRect(seg);
            g.setColour(juce::Colour(0xFF333333));
            g.drawRect(seg, 1.0f);
        }
    }
}

void AetherAudioProcessorEditor::resized() {
    syncMenu.setBounds(850, 60, 150, 30);
    timeSlider.setBounds(750, 45, 80, 80);
    stepCountSlider.setBounds(40, 700, 1020, 30);
    stepCountSlider.setAlpha(0.0f); 
}
\`;

