    syncMenu.addItem("1/1t", 14); syncMenu.addItem("1/2t", 15); syncMenu.addItem("1/4t", 16);
    syncMenu.addItem("1/8t", 17); syncMenu.addItem("1/16t", 18); syncMenu.addItem("1/32t", 19);

