void AetherAudioProcessorEditor::drawDice(juce::Graphics& g, int x, int y, int size) {
    g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.6f));
    // FIX: Using integer 2 instead of 2.0f for drawRect thickness when using int coordinates
    g.drawRect(x, y, size, size, 2); 
    float dotSize = size * 0.15f;
    // Simple 5-dot dice pattern
    g.fillEllipse(x + size*0.2, y + size*0.2, dotSize, dotSize);
    g.fillEllipse(x + size*0.7, y + size*0.2, dotSize, dotSize);
    g.fillEllipse(x + size*0.45, y + size*0.45, dotSize, dotSize);
    g.fillEllipse(x + size*0.2, y + size*0.7, dotSize, dotSize);
    g.fillEllipse(x + size*0.7, y + size*0.7, dotSize, dotSize);
}

void AetherAudioProcessorEditor::handleLaneInteraction(const juce::MouseEvent& e, bool isClick) {
    int laneStartY = 180;
    int spacing = 160;

    // LOCK TO ACTIVE LANE DURING DRAG
    if (activeDraggingLaneIndex != -1 && !isClick) {
        int l = activeDraggingLaneIndex;
        int currentLaneY = laneStartY + (l * spacing);
        float stepW = 1020.0f / 16.0f;
        int stepIdx = juce::jlimit(0, 15, (int)((e.x - 40) / stepW));
        auto& step = audioProcessor.steps[stepIdx];
        auto& lane = lanes[l];

        if (lane.propertyId != "muted") {
            // Calculate normalized Y relative to THE STARTING LANE, not where mouse is currently
            float normY = 1.0f - (float)(e.y - currentLaneY) / 88.0f;
            normY = juce::jlimit(0.0f, 1.0f, normY);
            int val = (int)(lane.min + normY * (lane.max - lane.min));
            if (lane.propertyId == "pitch") step.pitchOffset = val;
            else if (lane.propertyId == "velocity") step.velocity = val;
            else if (lane.propertyId == "modwheel") step.modwheel = val;
            else if (lane.propertyId == "probability") step.probability = val;
            repaint();
        }
        return;
    }

    for (int l = 0; l < (int)lanes.size(); ++l) {
        int currentLaneY = laneStartY + (l * spacing);

        // DICE HIT TEST
        juce::Rectangle<int> diceArea(40, currentLaneY - 30, 24, 24);
        if (isClick && diceArea.contains(e.x, e.y)) {
            juce::Random r;
            auto& lane = lanes[l];
            for(auto& s : audioProcessor.steps) {
                if (lane.propertyId == "pitch") s.pitchOffset = r.nextInt(juce::Range<int>(-24, 25));
                else if (lane.propertyId == "velocity") s.velocity = r.nextInt(juce::Range<int>(1, 128));
                else if (lane.propertyId == "modwheel") s.modwheel = r.nextInt(juce::Range<int>(0, 128));
                else if (lane.propertyId == "probability") s.probability = r.nextInt(juce::Range<int>(0, 101));
                else if (lane.propertyId == "muted") s.muted = r.nextBool();
            }
            repaint(); return;
        }

        // LANE HIT TEST
        juce::Rectangle<int> laneArea(40, currentLaneY, 1020, 112); // bar area + text space
        if (laneArea.contains(e.x, e.y)) {
            activeDraggingLaneIndex = l;
            float stepW = 1020.0f / 16.0f;
            int stepIdx = juce::jlimit(0, 15, (int)((e.x - 40) / stepW));
            auto& step = audioProcessor.steps[stepIdx];
            auto& lane = lanes[l];

            if (lane.propertyId == "muted") {
                if (isClick) step.muted = !step.muted;
            } else {
                float normY = 1.0f - (float)(e.y - currentLaneY) / 88.0f;
                normY = juce::jlimit(0.0f, 1.0f, normY);
                int val = (int)(lane.min + normY * (lane.max - lane.min));
                if (lane.propertyId == "pitch") step.pitchOffset = val;
                else if (lane.propertyId == "velocity") step.velocity = val;
                else if (lane.propertyId == "modwheel") step.modwheel = val;
                else if (lane.propertyId == "probability") step.probability = val;
            }
            repaint(); return;
        }
    }

    // Step Count Interaction
    juce::Rectangle<int> stepCountArea(40, 930, 1020, 30);
    if (stepCountArea.contains(e.x, e.y)) {
        float normX = (float)(e.x - 40) / 1020.0f;
        audioProcessor.activeStepCount = juce::jlimit(1, 16, (int)std::ceil(normX * 16.0f));
        repaint();
    }
}

void AetherAudioProcessorEditor::mouseDown (const juce::MouseEvent& e) { handleLaneInteraction(e, true); }
void AetherAudioProcessorEditor::mouseDrag (const juce::MouseEvent& e) { handleLaneInteraction(e, false); }
void AetherAudioProcessorEditor::mouseUp (const juce::MouseEvent& e) { activeDraggingLaneIndex = -1; }

void AetherAudioProcessorEditor::paint (juce::Graphics& g) {
    g.fillAll (juce::Colour(0xFF121212));
    g.setColour (juce::Colour(0xFF00FF41));
    g.setFont (juce::Font ("IBM Plex Mono", 64.0f, juce::Font::bold));
    g.drawText ("AETHER", 40, 40, 400, 70, juce::Justification::left);
    g.setFont (14.0f); g.setOpacity(0.6f);
    g.drawText ("Polyphonic MIDI Delay", 45, 110, 400, 20, juce::Justification::left);

    int laneStartY = 180;
    int spacing = 160;
    for (int l = 0; l < (int)lanes.size(); ++l) {
        int laneY = laneStartY + (l * spacing);
        auto& lane = lanes[l];

        drawDice(g, 40, laneY - 28, 20);
        g.setOpacity(0.8f);
        g.setFont (juce::Font ("IBM Plex Mono", 18.0f, juce::Font::bold));
        g.drawText(lane.label.toUpperCase(), 75, laneY - 30, 200, 25, juce::Justification::left);

        float stepW = 1020.0f / 16.0f;
        int barAreaH = 88;

        for (int i = 0; i < 16; ++i) {
            auto& step = audioProcessor.steps[i];
            float opacity = (i >= audioProcessor.activeStepCount) ? 0.2f : 1.0f;
            g.setColour(juce::Colour(0xFF2A2A2A));
            g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY, stepW * 0.8f, (float)barAreaH);
            g.setColour(juce::Colour(0xFF00FF41).withAlpha(opacity));

            int val = 0; juce::String valStr = "";
            if (lane.propertyId == "pitch") { val = step.pitchOffset; valStr = (val > 0 ? "+" : "") + juce::String(val); }
            else if (lane.propertyId == "velocity") { val = step.velocity; valStr = juce::String(val); }
            else if (lane.propertyId == "modwheel") { val = step.modwheel; valStr = juce::String(val); }
            else if (lane.propertyId == "probability") { val = step.probability; valStr = juce::String(val) + "%"; }
            else if (lane.propertyId == "muted") { valStr = step.muted ? "OFF" : "ON"; }

            if (lane.propertyId == "muted") {
                juce::Rectangle<float> muteBox(40.0f + i * stepW + 8, (float)laneY + 8, stepW - 16, (float)barAreaH - 16);
                if (!step.muted) { g.fillRect(muteBox); g.setColour(juce::Colour(0xFF000000)); g.fillEllipse(muteBox.getCentreX()-3, muteBox.getCentreY()-3, 6, 6); }
                else { g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.1f * opacity)); g.drawRect(muteBox, 1.0f); }
            } else if (lane.isBipolar) {
                float halfH = barAreaH / 2.0f;
                float h = (std::abs((float)val) / (float)lane.max) * halfH;
                if (val >= 0) g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY + halfH - h, stepW * 0.8f, h);
                else g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY + halfH, stepW * 0.8f, h);
                g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.2f * opacity));
                g.drawHorizontalLine(laneY + (int)halfH, (int)(40.0f + i * stepW), (int)(40.0f + (i + 1) * stepW));
            } else {
                float h = ((float)(val - lane.min) / (float)(lane.max - lane.min)) * barAreaH;
                g.fillRect(40.0f + i * stepW + (stepW * 0.1f), (float)laneY + (barAreaH - h), stepW * 0.8f, h);
            }
            g.setColour(juce::Colour(0xFF00FF41).withAlpha(opacity * 0.9f));
            g.setFont(juce::Font("IBM Plex Mono", 11.0f, juce::Font::bold));
            g.drawText(valStr, (int)(40.0f + i * stepW), laneY + barAreaH + 2, (int)stepW, 20, juce::Justification::centred);
        }
    }

    g.setColour(juce::Colour(0xFF00FF41));
    g.setFont(juce::Font ("IBM Plex Mono", 12.0f, juce::Font::bold));
    g.drawText("STEP COUNT", 40, 910, 200, 15, juce::Justification::left);
    g.drawText(juce::String(audioProcessor.activeStepCount) + " STEPS", 900, 910, 160, 15, juce::Justification::right);
    float segW = 1020.0f / 16.0f;
    for (int i = 0; i < 16; ++i) {
        juce::Rectangle<float> seg(40.0f + i * segW + 1, 930, segW - 2, 30);
        g.setColour(i < audioProcessor.activeStepCount ? juce::Colour(0xFF00FF41) : juce::Colour(0xFF1A1A1A));
        g.fillRect(seg);
        if (i < audioProcessor.activeStepCount) { g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.2f)); g.drawRect(seg.expanded(1.0f), 1.0f); }
        else { g.setColour(juce::Colour(0xFF333333)); g.drawRect(seg, 1.0f); }
    }
}

void AetherAudioProcessorEditor::resized() {
    syncMenu.setBounds(850, 60, 150, 30);
    timeSlider.setBounds(750, 45, 80, 80);
}
