export type DelayMode = 'ms' | 'sync';

export type Step = {
  pitch: number;        // -24 to 24
  velocity: number;     // 1 to 127
  modwheel: number;     // 0 to 127
  probability: number;  // 0 to 100
  muted: boolean;
};

export type PluginState = {
  delayMode: DelayMode;
  delayTimeMs: number;
  syncDivision: string;
  stepCount: number;    // 1 to 16
  steps: Step[];
  transportSync: boolean;
};

export const INITIAL_STATE: PluginState = {
  delayMode: 'sync',
  delayTimeMs: 500,
  syncDivision: '1/4',
  stepCount: 16,
  transportSync: false,
  steps: Array.from({ length: 16 }, (_, i) => ({
    pitch: 0,
    velocity: Math.round(127 - (i * (126 / 15))),
    modwheel: 0,
    probability: 100,
    muted: false,
  })),
};

export const NOTE_NAMES = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
export const getNoteName = (midi: number) => {
  const name = NOTE_NAMES[midi % 12];
  const oct = Math.floor(midi / 12) - 1;
  return `${name}${oct}`;
};

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { INITIAL_STATE, PluginState, Step } from './types';
import { StepLane } from './components/StepLane';
import { Knob } from './components/Knob';
import { CodeExporter } from './components/CodeExporter';

const OPTIONS = [
  'ms',
  '1/1', '1/2', '1/4', '1/8', '1/16', '1/32',
  '1/1d', '1/2d', '1/4d', '1/8d', '1/16d', '1/32d',
  '1/1t', '1/2t', '1/4t', '1/8t', '1/16t', '1/32t'
];

const App: React.FC = () => {
  const [state, setState] = useState<PluginState>(INITIAL_STATE);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isExporterOpen, setIsExporterOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const stepCountRef = useRef<HTMLDivElement>(null);
  const isDraggingStepCount = useRef(false);

  const updateStep = useCallback((index: number, value: number | boolean, property: keyof Step) => {
    setState(prev => {
      const newSteps = [...prev.steps];
      newSteps[index] = { ...newSteps[index], [property]: value };
      return { ...prev, steps: newSteps };
    });
  }, []);

  const randomizeLane = useCallback((property: keyof Step, min: number, max: number) => {
    setState(prev => {
      const newSteps = prev.steps.map(step => {
        let newVal: any;
        if (property === 'muted') {
          newVal = Math.random() > 0.5;
        } else {
          newVal = Math.round(min + Math.random() * (max - min));
        }
        return { ...step, [property]: newVal };
      });
      return { ...prev, steps: newSteps };
    });
  }, []);

  const handleStepCountInteraction = (clientX: number) => {
    if (!stepCountRef.current) return;
    const rect = stepCountRef.current.getBoundingClientRect();
    const width = rect.width;
    const relativeX = Math.max(0, Math.min(width, clientX - rect.left));
    const normalized = relativeX / width;
    const newCount = Math.max(1, Math.min(16, Math.ceil(normalized * 16)));
    setState(prev => ({ ...prev, stepCount: newCount }));
  };

  const onStepCountMouseDown = (e: React.MouseEvent) => {
    isDraggingStepCount.current = true;
    handleStepCountInteraction(e.clientX);
  };

  const onStepCountMouseMove = (e: React.MouseEvent) => {
    if (isDraggingStepCount.current) {
      handleStepCountInteraction(e.clientX);
    }
  };

  useEffect(() => {
    const handleMouseUp = () => {
      isDraggingStepCount.current = false;
    };
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('mousedown', handleClickOutside);
    return () => {
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const isMsMode = state.syncDivision === 'ms';

  return (
    <div className="flex flex-col min-h-screen items-center justify-center p-4 bg-[#050505]">

      {/* Exporter Overlay */}
      {isExporterOpen && <CodeExporter onClose={() => setIsExporterOpen(false)} />}

      {/* Exporter Toggle - Outside main UI */}
      <div className="mb-4">
        <button 
          onClick={() => setIsExporterOpen(true)}
          className="px-6 py-2 border border-[#00ff41]/40 text-[#00ff41] text-[10px] font-bold uppercase tracking-widest hover:bg-[#00ff41] hover:text-black transition-all cursor-pointer shadow-[0_0_10px_rgba(0,255,65,0.1)]"
        >
          Export C++ Files (JUCE)
        </button>
      </div>

      {/* Main Plugin Container */}
      <div className="w-full max-w-[1100px] h-fit bg-[#121212] crt-border p-8 flex flex-col gap-4 overflow-hidden relative">

        {/* Header */}
        <div className="flex justify-between items-center border-b border-green-500/20 pb-4">
          <div className="flex flex-col justify-center">
            <h1 className="text-[4.125rem] font-black tracking-tighter crt-glow leading-[0.85]">AETHER</h1>
            <div className="mt-2 flex flex-col">
              <p className="text-[13px] uppercase tracking-widest text-[#00ff41] opacity-60">Polyphonic MIDI Delay</p>
              <p className="text-[12px] uppercase tracking-widest text-[#00ff41] opacity-60 mt-0.5">by darkInteger</p>
            </div>
          </div>

          <div className="flex gap-10 items-center">
            {/* Transport Sync Toggle */}
            <div className="flex flex-col items-center gap-1">
              <span className="text-[9px] uppercase font-bold tracking-widest opacity-60">Transport</span>
              <button 
                onClick={() => setState(p => ({ ...p, transportSync: !p.transportSync }))}
                className={`px-3 py-1 border text-[10px] font-bold transition-all ${state.transportSync ? 'bg-[#00ff41] text-black border-[#00ff41]' : 'bg-transparent text-[#00ff41] border-[#00ff41]/40'}`}
              >
                {state.transportSync ? 'DAW SYNC ON' : 'DAW SYNC OFF'}
              </button>
            </div>

            {isMsMode && (
              <Knob 
                label="Time" 
                value={state.delayTimeMs} 
                min={1} 
                max={1000} 
                suffix="ms"
                onChange={(v) => setState(p => ({ ...p, delayTimeMs: v }))} 
              />
            )}

            <div className="flex flex-col gap-2 relative" ref={dropdownRef}>
              <label className="text-[10px] uppercase font-bold opacity-60">Delay Time</label>

              <div 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)}
                className="bg-[#121212] border border-[#00ff41] px-3 py-1.5 text-xs text-[#00ff41] font-bold cursor-pointer min-w-[140px] flex justify-between items-center"
              >
                <span className="crt-glow">{state.syncDivision === 'ms' ? 'MILLISEC (ms)' : state.syncDivision}</span>
                <span className="ml-2 text-[8px] transform transition-transform" style={{ transform: isDropdownOpen ? 'rotate(180deg)' : 'rotate(0deg)' }}>▼</span>
              </div>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 mt-1 bg-[#121212] border border-[#00ff41] z-[200] min-w-full w-max overflow-visible shadow-[0_10px_30px_rgba(0,0,0,0.8)]">
                  {OPTIONS.map(d => (
                    <div 
                      key={d} 
                      onClick={() => {
                        setState(p => ({ ...p, syncDivision: d }));
                        setIsDropdownOpen(false);
                      }}
                      className={`px-3 py-1.5 text-xs cursor-pointer hover:bg-[#00ff41] hover:text-black transition-colors ${state.syncDivision === d ? 'text-[#00ff41] bg-[#00ff41]/10 font-bold' : 'text-[#00ff41]/80'}`}
                    >
                      {d === 'ms' ? 'MILLISEC (ms)' : d}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Lanes */}
        <div className="flex flex-col gap-4">
          <StepLane 
            label="Pitch Shift" 
            property="pitch" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={-24} max={24} 
            isBipolar 
            onUpdate={(i, v) => updateStep(i, v, 'pitch')}
            onRandomize={() => randomizeLane('pitch', -24, 24)}
          />
          <StepLane 
            label="Velocity" 
            property="velocity" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={1} max={127} 
            onUpdate={(i, v) => updateStep(i, v, 'velocity')}
            onRandomize={() => randomizeLane('velocity', 1, 127)}
          />
          <StepLane 
            label="Modwheel" 
            property="modwheel" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={127} 
            onUpdate={(i, v) => updateStep(i, v, 'modwheel')}
            onRandomize={() => randomizeLane('modwheel', 0, 127)}
          />
          <StepLane 
            label="Probability" 
            property="probability" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={100} 
            onUpdate={(i, v) => updateStep(i, v, 'probability')}
            onRandomize={() => randomizeLane('probability', 0, 100)}
          />
          <StepLane 
            label="Mute" 
            property="muted" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={1} 
            onUpdate={(i, v) => updateStep(i, v, 'muted')}
            onRandomize={() => randomizeLane('muted', 0, 1)}
          />

          {/* Step Count Slider */}
          <div className="flex flex-col gap-1 mt-4 pb-2">
            <div className="flex justify-between items-end px-1">
              <span className="text-[10px] font-bold uppercase tracking-widest opacity-70">Step Count</span>
              <span className="text-[10px] font-bold text-[#00ff41] crt-glow">{state.stepCount} STEPS</span>
            </div>
            <div 
              ref={stepCountRef}
              onMouseDown={onStepCountMouseDown}
              onMouseMove={onStepCountMouseMove}
              className="h-6 bg-[#1a1a1a] border border-[#333] flex items-stretch gap-[2px] p-[2px] cursor-pointer relative"
            >
              {Array.from({ length: 16 }).map((_, i) => (
                <div 
                  key={i} 
                  className={`flex-1 transition-colors ${i < state.stepCount ? 'bg-[#00ff41]' : 'bg-green-900/10'}`}
                >
                  <div className={`h-full w-full ${i < state.stepCount ? 'shadow-[0_0_5px_#00ff4155]' : ''}`}></div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useRef, useCallback, useEffect } from 'react';
import { Step } from '../types';

interface StepLaneProps {
  label: string;
  property: keyof Step;
  steps: Step[];
  stepCount: number;
  min: number;
  max: number;
  isBipolar?: boolean;
  onUpdate: (index: number, value: number | boolean) => void;
  onRandomize: () => void;
}

const LABEL_HEIGHT = 24;

const DiceIcon = () => (
  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="opacity-80">
    <rect x="3" y="3" width="18" height="18" rx="2" ry="2" />
    <circle cx="8.5" cy="8.5" r="1.5" fill="currentColor" />
    <circle cx="15.5" cy="15.5" r="1.5" fill="currentColor" />
    <circle cx="12" cy="12" r="1.5" fill="currentColor" />
  </svg>
);

export const StepLane: React.FC<StepLaneProps> = ({ 
  label, property, steps, stepCount, min, max, isBipolar, onUpdate, onRandomize 
}) => {
  const laneRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);

  const calculateValue = useCallback((clientY: number) => {
    if (!laneRef.current) return 0;
    const rect = laneRef.current.getBoundingClientRect();
    const barAreaHeight = rect.height - (property === 'muted' ? 0 : LABEL_HEIGHT);
    const relativeY = Math.max(0, Math.min(barAreaHeight, clientY - rect.top));
    const normalized = 1 - (relativeY / barAreaHeight);
    return Math.round(min + (normalized * (max - min)));
  }, [min, max, property]);

  const updateFromMouseEvent = useCallback((e: MouseEvent | React.MouseEvent) => {
    if (!laneRef.current) return;
    const rect = laneRef.current.getBoundingClientRect();
    const relativeX = e.clientX - rect.left;
    const stepWidth = rect.width / 16;
    const index = Math.max(0, Math.min(15, Math.floor(relativeX / stepWidth)));

    if (property === 'muted') return;

    const value = calculateValue(e.clientY);
    onUpdate(index, value);
  }, [calculateValue, onUpdate, property]);

  const onMouseDown = (e: React.MouseEvent, index: number) => {
    isDragging.current = true;
    if (property === 'muted') {
      onUpdate(index, !steps[index].muted);
    } else {
      updateFromMouseEvent(e);
    }
  };

  useEffect(() => {
    const handleGlobalMouseMove = (e: MouseEvent) => {
      if (isDragging.current) updateFromMouseEvent(e);
    };
    const handleGlobalMouseUp = () => {
      isDragging.current = false;
    };
    window.addEventListener('mousemove', handleGlobalMouseMove);
    window.addEventListener('mouseup', handleGlobalMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleGlobalMouseMove);
      window.removeEventListener('mouseup', handleGlobalMouseUp);
    };
  }, [updateFromMouseEvent]);

  const formatValue = (val: number | boolean) => {
    if (typeof val === 'boolean') return ''; // Don't show text for Mute lane
    if (property === 'probability') return `${val}%`;
    if (property === 'pitch' && val > 0) return `+${val}`;
    return val.toString();
  };

  return (
    <div className="flex flex-col gap-1">
      <div className="flex justify-between items-end px-1 mb-1">
        <div className="flex items-center gap-3">
          <button 
            onClick={(e) => { e.stopPropagation(); onRandomize(); }}
            className="hover:text-white transition-colors p-0.5 border border-transparent hover:border-green-500/30 rounded active:scale-90"
            title="Randomize Lane"
          >
            <DiceIcon />
          </button>
          <span className="text-[16px] font-bold uppercase tracking-widest opacity-70">{label}</span>
        </div>
      </div>

      <div 
        ref={laneRef}
        className={`${property === 'muted' ? 'h-22' : 'h-28'} bg-transparent flex items-stretch gap-[1px] relative overflow-hidden`}
      >
        {isBipolar && (
          <div 
            className="absolute left-0 right-0 h-[1px] bg-green-500/20 pointer-events-none z-10"
            style={{ top: `calc(50% - ${LABEL_HEIGHT / 2}px)` }}
          ></div>
        )}

        {steps.map((step, i) => {
          const val = step[property];
          const isMuted = step.muted || i >= stepCount;

          return (
            <div
              key={i}
              onMouseDown={(e) => onMouseDown(e, i)}
              className={`flex-1 flex flex-col relative cursor-crosshair group transition-opacity ${isMuted ? 'opacity-20' : 'opacity-100'}`}
            >
              <div className="flex-1 relative">
                <div className="absolute inset-y-0 left-[10%] right-[10%] bg-[#2a2a2a] pointer-events-none"></div>

                {property === 'muted' ? (
                   <div className={`absolute inset-2 border transition-colors flex items-center justify-center z-20 ${step.muted ? 'bg-transparent border-green-900/30' : 'bg-[#00ff41] border-[#00ff41]'}`}>
                      {!step.muted && <div className="w-1.5 h-1.5 bg-black rounded-full shadow-[0_0_4px_#000]"></div>}
                   </div>
                ) : isBipolar ? (
                  <div 
                    className="absolute left-[10%] right-[10%] bg-[#00ff41] shadow-[0_0_8px_#00ff4155] pointer-events-none z-20"
                    style={{ 
                      top: (val as number) >= 0 ? '50%' : `${50 - (Math.abs(val as number)/max * 50)}%`,
                      bottom: (val as number) >= 0 ? `${50 - (Math.abs(val as number)/max * 50)}%` : '50%',
                      transform: (val as number) >= 0 ? 'translateY(-100%)' : 'translateY(100%)'
                    }}
                  ></div>
                ) : (
                  <div 
                    className="absolute bottom-0 left-[10%] right-[10%] bg-[#00ff41] shadow-[0_0_8px_#00ff4155] pointer-events-none z-20"
                    style={{ height: `${((val as number - min) / (max - min)) * 100}%` }}
                  ></div>
                )}
              </div>
              {property !== 'muted' && (
                <div 
                  className="flex items-center justify-center text-[11px] font-black text-[#00ff41]/90 select-none pointer-events-none border-t border-white/5 mt-[1px]"
                  style={{ height: `${LABEL_HEIGHT}px` }}
                >
                  {formatValue(val)}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

