        >
          Export C++ Files (JUCE)
        </button>
      </div>

      {/* Main Plugin Container */}
      <div className={`w-full max-w-[1100px] h-fit bg-[#121212] crt-border p-8 flex flex-col gap-4 overflow-hidden relative transition-opacity duration-500 ${!state.isEnabled ? 'opacity-40 grayscale-[0.5]' : 'opacity-100'}`}>

        {/* Header */}
        <div className="flex justify-between items-center border-b border-green-500/20 pb-6">
          <div className="flex items-center gap-8">
            {/* Power Button */}
            <div className="flex flex-col items-center gap-2">
               <span className="text-[9px] uppercase font-bold tracking-widest opacity-60">Power</span>
               <button 
                onClick={() => setState(p => ({ ...p, isEnabled: !p.isEnabled }))}
                className={`w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${state.isEnabled ? 'bg-[#00ff41] border-[#00ff41] text-black shadow-[0_0_15px_rgba(0,255,65,0.5)]' : 'bg-transparent border-[#00ff41]/20 text-[#00ff41]/20'}`}
               >
                 <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M18.36 6.64a9 9 0 1 1-12.73 0" />
                    <line x1="12" y1="2" x2="12" y2="12" />
                 </svg>
               </button>
            </div>

            <div className="flex flex-col justify-center">
              <h1 className="text-[4.125rem] font-black tracking-tighter crt-glow leading-[0.85]">AETHER</h1>
              <div className="mt-2 flex flex-col">
                <p className="text-[13px] uppercase tracking-widest text-[#00ff41] opacity-60">Polyphonic MIDI Delay</p>
                <p className="text-[12px] uppercase tracking-widest text-[#00ff41] opacity-60 mt-0.5">by darkInteger</p>
              </div>
            </div>
          </div>

          <div className="flex gap-10 items-end h-full pt-4">
            {/* Kill On Stop Toggle */}
            <div className="flex flex-col items-center gap-2">
              <span className="text-[9px] uppercase font-bold tracking-widest opacity-60">Transport</span>
              <button 
                onClick={() => setState(p => ({ ...p, killOnStop: !p.killOnStop }))}
                className={`px-4 py-1.5 border text-[10px] font-bold transition-all ${state.killOnStop ? 'bg-[#00ff41] text-black border-[#00ff41]' : 'bg-transparent text-[#00ff41] border-[#00ff41]/40'}`}
              >
                {state.killOnStop ? 'KILL ON STOP' : 'CONTINUE ON STOP'}
              </button>
            </div>

            {isMsMode && (
              <Knob 
                label="Time" 
                value={state.delayTimeMs} 
                min={1} 
                max={1000} 
                suffix="ms"
                onChange={(v) => setState(p => ({ ...p, delayTimeMs: v }))} 
              />
            )}

            <div className="flex flex-col gap-2 relative mb-1" ref={dropdownRef}>
              <label className="text-[10px] uppercase font-bold opacity-60">Delay Time</label>

              <div 
                onClick={() => setState(p => p.isEnabled ? { ...p } : p) || setIsDropdownOpen(!isDropdownOpen)}
                className="bg-[#121212] border border-[#00ff41] px-3 py-1.5 text-xs text-[#00ff41] font-bold cursor-pointer min-w-[140px] flex justify-between items-center"
              >
                <span className="crt-glow">{state.syncDivision === 'ms' ? 'MILLISEC (ms)' : state.syncDivision}</span>
                <span className="ml-2 text-[8px] transform transition-transform" style={{ transform: isDropdownOpen ? 'rotate(180deg)' : 'rotate(0deg)' }}>▼</span>
              </div>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 mt-1 bg-[#121212] border border-[#00ff41] z-[200] min-w-full w-max shadow-[0_10px_30px_rgba(0,0,0,0.8)]">
                  {OPTIONS.map(d => (
                    <div 
                      key={d} 
                      onClick={() => {
                        setState(p => ({ ...p, syncDivision: d }));
                        setIsDropdownOpen(false);
                      }}
                      className={`px-3 py-1.5 text-xs cursor-pointer hover:bg-[#00ff41] hover:text-black transition-colors ${state.syncDivision === d ? 'text-[#00ff41] bg-[#00ff41]/10 font-bold' : 'text-[#00ff41]/80'}`}
                    >
                      {d === 'ms' ? 'MILLISEC (ms)' : d}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Lanes */}
        <div className={`flex flex-col gap-4 transition-all duration-300 ${!state.isEnabled ? 'pointer-events-none' : ''}`}>
          <StepLane 
            label="Pitch Shift" 
            property="pitch" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={-24} max={24} 
            isBipolar 
            onUpdate={(i, v) => updateStep(i, v, 'pitch')}
            onRandomize={() => randomizeLane('pitch', -24, 24)}
          />
          <StepLane 
            label="Velocity" 
            property="velocity" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={1} max={127} 
            onUpdate={(i, v) => updateStep(i, v, 'velocity')}
            onRandomize={() => randomizeLane('velocity', 1, 127)}
          />
          <StepLane 
            label="Modwheel" 
            property="modwheel" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={127} 
            onUpdate={(i, v) => updateStep(i, v, 'modwheel')}
            onRandomize={() => randomizeLane('modwheel', 0, 127)}
          />
          <StepLane 
            label="Probability" 
            property="probability" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={100} 
            onUpdate={(i, v) => updateStep(i, v, 'probability')}
