// C++ Code Templates
const processorH = `// PluginProcessor.h
#pragma once
#include <JuceHeader.h>

struct DelayStep {
    int pitchOffset = 0;
    int velocity = 100;
    int modwheel = 0;
    int probability = 100;
    bool muted = false;
};

struct QueuedEvent {
    juce::MidiMessage message;
