import React, { useState, useCallback, useRef, useEffect } from 'react';
import { INITIAL_STATE, PluginState, Step } from './types';
import { StepLane } from './components/StepLane';
import { Knob } from './components/Knob';
import { CodeExporter } from './components/CodeExporter';

const OPTIONS = [
  'ms',
  '1/1', '1/2', '1/4', '1/8', '1/16', '1/32',
  '1/1d', '1/2d', '1/4d', '1/8d', '1/16d', '1/32d',
  '1/1t', '1/2t', '1/4t', '1/8t', '1/16t', '1/32t'
];

const App: React.FC = () => {
  const [state, setState] = useState<PluginState>(INITIAL_STATE);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [isExporterOpen, setIsExporterOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const stepCountRef = useRef<HTMLDivElement>(null);
  const isDraggingStepCount = useRef(false);

  const updateStep = useCallback((index: number, value: number | boolean, property: keyof Step) => {
    setState(prev => {
      const newSteps = [...prev.steps];
      newSteps[index] = { ...newSteps[index], [property]: value };
      return { ...prev, steps: newSteps };
    });
  }, []);

  const randomizeLane = useCallback((property: keyof Step, min: number, max: number) => {
    setState(prev => {
      const newSteps = prev.steps.map(step => {
        let newVal: any;
        if (property === 'muted') {
          newVal = Math.random() > 0.5;
        } else {
          newVal = Math.round(min + Math.random() * (max - min));
        }
        return { ...step, [property]: newVal };
      });
      return { ...prev, steps: newSteps };
    });
  }, []);

  const handleStepCountInteraction = (clientX: number) => {
    if (!stepCountRef.current) return;
    const rect = stepCountRef.current.getBoundingClientRect();
    const width = rect.width;
    const relativeX = Math.max(0, Math.min(width, clientX - rect.left));
    const normalized = relativeX / width;
    const newCount = Math.max(1, Math.min(16, Math.ceil(normalized * 16)));
    setState(prev => ({ ...prev, stepCount: newCount }));
  };

  const onStepCountMouseDown = (e: React.MouseEvent) => {
    isDraggingStepCount.current = true;
    handleStepCountInteraction(e.clientX);
  };

  const onStepCountMouseMove = (e: React.MouseEvent) => {
    if (isDraggingStepCount.current) {
      handleStepCountInteraction(e.clientX);
    }
  };

  useEffect(() => {
    const handleMouseUp = () => {
      isDraggingStepCount.current = false;
    };
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('mousedown', handleClickOutside);
    return () => {
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const isMsMode = state.syncDivision === 'ms';

  return (
    <div className="flex flex-col min-h-screen items-center justify-center p-4 bg-[#050505]">

      {/* Exporter Overlay */}
      {isExporterOpen && <CodeExporter onClose={() => setIsExporterOpen(false)} />}

      {/* Exporter Toggle */}
      <div className="mb-4">
        <button 
          onClick={() => setIsExporterOpen(true)}
          className="px-6 py-2 border border-[#00ff41]/40 text-[#00ff41] text-[10px] font-bold uppercase tracking-widest hover:bg-[#00ff41] hover:text-black transition-all cursor-pointer shadow-[0_0_10px_rgba(0,255,65,0.1)]"
        >
          Export C++ Files (JUCE)
        </button>
      </div>

      {/* Main Plugin Container */}
      <div className={`w-full max-w-[1100px] h-fit bg-[#121212] crt-border p-8 flex flex-col gap-4 overflow-hidden relative transition-opacity duration-500 ${!state.isEnabled ? 'opacity-40 grayscale-[0.5]' : 'opacity-100'}`}>

        {/* Header */}
        <div className="flex justify-between items-center border-b border-green-500/20 pb-6">
          <div className="flex items-center gap-8">
            {/* Power Button */}
            <div className="flex flex-col items-center gap-2">
               <span className="text-[9px] uppercase font-bold tracking-widest opacity-60">Power</span>
               <button 
                onClick={() => setState(p => ({ ...p, isEnabled: !p.isEnabled }))}
                className={`w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${state.isEnabled ? 'bg-[#00ff41] border-[#00ff41] text-black shadow-[0_0_15px_rgba(0,255,65,0.5)]' : 'bg-transparent border-[#00ff41]/20 text-[#00ff41]/20'}`}
               >
                 <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M18.36 6.64a9 9 0 1 1-12.73 0" />
                    <line x1="12" y1="2" x2="12" y2="12" />
                 </svg>
               </button>
            </div>

            <div className="flex flex-col justify-center">
              <h1 className="text-[4.125rem] font-black tracking-tighter crt-glow leading-[0.85]">AETHER</h1>
              <div className="mt-2 flex flex-col">
                <p className="text-[13px] uppercase tracking-widest text-[#00ff41] opacity-60">Polyphonic MIDI Delay</p>
                <p className="text-[12px] uppercase tracking-widest text-[#00ff41] opacity-60 mt-0.5">by darkInteger</p>
              </div>
            </div>
          </div>

          <div className="flex gap-10 items-end h-full pt-4">
            {/* Kill On Stop Toggle */}
            <div className="flex flex-col items-center gap-2">
              <span className="text-[9px] uppercase font-bold tracking-widest opacity-60">Transport</span>
              <button 
                onClick={() => setState(p => ({ ...p, killOnStop: !p.killOnStop }))}
                className={`px-4 py-1.5 border-2 text-[10px] font-bold transition-all w-32 h-10 flex items-center justify-center tracking-tighter ${state.killOnStop ? 'bg-[#00ff41] text-black border-[#00ff41]' : 'bg-transparent text-[#00ff41] border-[#00ff41]'}`}
              >
                KILL ON STOP
              </button>
            </div>

            {isMsMode && (
              <Knob 
                label="Time" 
                value={state.delayTimeMs} 
                min={1} 
                max={1000} 
                suffix="ms"
                onChange={(v) => setState(p => ({ ...p, delayTimeMs: v }))} 
              />
            )}

            <div className="flex flex-col gap-2 relative mb-1" ref={dropdownRef}>
              <label className="text-[10px] uppercase font-bold opacity-60">Delay Time</label>

              <div 
                onClick={() => setState(p => p.isEnabled ? { ...p } : p) || setIsDropdownOpen(!isDropdownOpen)}
                className="bg-[#121212] border border-[#00ff41] px-3 py-1.5 text-xs text-[#00ff41] font-bold cursor-pointer min-w-[140px] flex justify-between items-center"
              >
                <span className="crt-glow">{state.syncDivision === 'ms' ? 'MILLISEC (ms)' : state.syncDivision}</span>
                <span className="ml-2 text-[8px] transform transition-transform" style={{ transform: isDropdownOpen ? 'rotate(180deg)' : 'rotate(0deg)' }}>▼</span>
              </div>

              {isDropdownOpen && (
                <div className="absolute top-full left-0 mt-1 bg-[#121212] border border-[#00ff41] z-[200] min-w-full w-max shadow-[0_10px_30px_rgba(0,0,0,0.8)]">
                  {OPTIONS.map(d => (
                    <div 
                      key={d} 
                      onClick={() => {
                        setState(p => ({ ...p, syncDivision: d }));
                        setIsDropdownOpen(false);
                      }}
                      className={`px-3 py-1.5 text-xs cursor-pointer hover:bg-[#00ff41] hover:text-black transition-colors ${state.syncDivision === d ? 'text-[#00ff41] bg-[#00ff41]/10 font-bold' : 'text-[#00ff41]/80'}`}
                    >
                      {d === 'ms' ? 'MILLISEC (ms)' : d}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Lanes */}
        <div className={`flex flex-col gap-4 transition-all duration-300 ${!state.isEnabled ? 'pointer-events-none' : ''}`}>
          <StepLane 
            label="Pitch Shift" 
            property="pitch" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={-24} max={24} 
            isBipolar 
            onUpdate={(i, v) => updateStep(i, v, 'pitch')}
            onRandomize={() => randomizeLane('pitch', -24, 24)}
          />
          <StepLane 
            label="Velocity" 
            property="velocity" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={1} max={127} 
            onUpdate={(i, v) => updateStep(i, v, 'velocity')}
            onRandomize={() => randomizeLane('velocity', 1, 127)}
          />
          <StepLane 
            label="Modwheel" 
            property="modwheel" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={127} 
            onUpdate={(i, v) => updateStep(i, v, 'modwheel')}
            onRandomize={() => randomizeLane('modwheel', 0, 127)}
          />
          <StepLane 
            label="Probability" 
            property="probability" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={100} 
            onUpdate={(i, v) => updateStep(i, v, 'probability')}
            onRandomize={() => randomizeLane('probability', 0, 100)}
          />
          <StepLane 
            label="Mute" 
            property="muted" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={1} 
            onUpdate={(i, v) => updateStep(i, v, 'muted')}
            onRandomize={() => randomizeLane('muted', 0, 1)}
          />

          {/* Step Count Slider */}
          <div className="flex flex-col gap-1 mt-4 pb-2">
            <div className="flex justify-between items-end px-1">
              <span className="text-[12px] font-bold text-[#00ff41] crt-glow uppercase tracking-widest opacity-90">STEP COUNT: {state.stepCount}</span>
            </div>
            <div 
              ref={stepCountRef}
              onMouseDown={onStepCountMouseDown}
              onMouseMove={onStepCountMouseMove}
              className="h-6 bg-[#1a1a1a] border border-[#333] flex items-stretch gap-[2px] p-[2px] cursor-pointer relative"
            >
              {Array.from({ length: 16 }).map((_, i) => (
                <div 
                  key={i} 
                  className={`flex-1 transition-colors ${i < state.stepCount ? 'bg-[#00ff41]' : 'bg-green-900/10'}`}
                >
                  <div className={`h-full w-full ${i < state.stepCount ? 'shadow-[0_0_5px_#00ff4155]' : ''}`}></div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface CodeExporterProps {
  onClose: () => void;
}

export const CodeExporter: React.FC<CodeExporterProps> = ({ onClose }) => {
  const [activeTab, setActiveTab] = useState(0);
  const [copied, setCopied] = useState(false);

  const tabs = [
    { name: 'PluginProcessor.h', code: processorH },
    { name: 'PluginProcessor.cpp', code: processorCpp },
    { name: 'PluginEditor.h', code: editorH },
    { name: 'PluginEditor.cpp', code: editorCpp },
  ];

  const handleCopy = () => {
    navigator.clipboard.writeText(tabs[activeTab].code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="fixed inset-0 z-[1000] bg-black/90 flex flex-col items-center justify-center p-8 backdrop-blur-sm">
      <div className="w-full max-w-6xl h-full flex flex-col bg-[#1a1a1a] border border-[#333] shadow-2xl overflow-hidden">
        {/* Header */}
        <div className="flex justify-between items-center px-6 py-4 border-b border-[#333] bg-[#222]">
          <div className="flex items-center gap-4">
            <h2 className="text-white font-bold tracking-tight">C++ EXPORTER (JUCE/VST3)</h2>
            <div className="flex gap-1">
              {tabs.map((tab, i) => (
                <button
                  key={tab.name}
                  onClick={() => setActiveTab(i)}
                  className={`px-4 py-2 text-xs font-mono transition-colors ${
                    activeTab === i ? 'bg-[#00ff41] text-black font-bold' : 'text-gray-400 hover:text-white'
                  }`}
                >
                  {tab.name}
                </button>
              ))}
            </div>
          </div>
          <div className="flex gap-4">
            <button
              onClick={handleCopy}
              className="px-4 py-2 bg-white/5 hover:bg-white/10 text-white text-xs font-bold transition-colors border border-white/10"
            >
              {copied ? 'COPIED!' : 'COPY CODE'}
            </button>
            <button
              onClick={onClose}
              className="px-4 py-2 text-gray-400 hover:text-white text-xs font-bold"
            >
              CLOSE
            </button>
          </div>
        </div>

        {/* Code Content */}
        <div className="flex-1 overflow-auto bg-[#0a0a0a] p-6">
          <pre className="text-sm font-mono leading-relaxed text-gray-300 selection:bg-[#00ff41] selection:text-black">
            <code>{tabs[activeTab].code}</code>
          </pre>
        </div>

        {/* Footer */}
        <div className="px-6 py-3 border-t border-[#333] bg-[#1a1a1a] text-[10px] text-gray-500 uppercase flex justify-between">
          <span>Target: JUCE 7.x / C++17</span>
          <span>Generated by AETHER Logic Engine</span>
        </div>
      </div>
    </div>
  );
};

// C++ Code Templates
const processorH = `// PluginProcessor.h
#pragma once
#include <JuceHeader.h>

struct DelayStep {
    int pitchOffset = 0;
    int velocity = 100;
    int modwheel = 0;
    int probability = 100;
    bool muted = false;
};

struct QueuedEvent {
    juce::MidiMessage message;
    long long targetSample;
};

class AetherAudioProcessor : public juce::AudioProcessor {
public:
    AetherAudioProcessor();
    ~AetherAudioProcessor() override;

    void prepareToPlay (double sampleRate, int samplesPerBlock) override;
    void releaseResources() override {}
    void processBlock (juce::AudioBuffer<float>&, juce::MidiBuffer&) override;

    juce::AudioProcessorEditor* createEditor() override;
    bool hasEditor() const override { return true; }

    const juce::String getName() const override { return "AETHER"; }
    bool acceptsMidi() const override { return true; }
    bool producesMidi() const override { return true; }
    double getTailLengthSeconds() const override { return 2.0; }

    int getNumPrograms() override { return 1; }
    int getCurrentProgram() override { return 0; }
    void setCurrentProgram (int) override {}
    const juce::String getProgramName (int) override { return {}; }
    void changeProgramName (int, const juce::String&) override {}

    void getStateInformation (juce::MemoryBlock& destData) override;
    void setStateInformation (const void* data, int sizeInBytes) override;

    // Public State - Accessed by Editor
    std::array<DelayStep, 16> steps;
    int activeStepCount = 16;
    double delayTimeMs = 500.0;
    int syncDivisionIndex = 3; 
    bool killOnStop = true;
    bool isEnabled = true;

private:
    double lastSampleRate = 44100.0;
    long long totalSamplesProcessed = 0;
    std::vector<QueuedEvent> midiQueue;
    juce::Random random;

    double getSyncTimeInMs();

    JUCE_DECLARE_NON_COPYABLE_WITH_LEAK_DETECTOR (AetherAudioProcessor)
};`;

const processorCpp = `// PluginProcessor.cpp
#include "PluginProcessor.h"
#include "PluginEditor.h"

AetherAudioProcessor::AetherAudioProcessor()
    : AudioProcessor (BusesProperties().withOutput ("Output", juce::AudioChannelSet::stereo(), true))
{
    // Initialize defaults
    isEnabled = true;
    delayTimeMs = 500.0;
    syncDivisionIndex = 3;
    activeStepCount = 16;
    killOnStop = true;

    for (int i = 0; i < 16; ++i) {
        steps[i].velocity = 127 - (i * 8);
        steps[i].modwheel = 0;
        steps[i].probability = 100;
        steps[i].pitchOffset = 0;
        steps[i].muted = false;
    }
}

AetherAudioProcessor::~AetherAudioProcessor() {}

void AetherAudioProcessor::prepareToPlay (double sampleRate, int samplesPerBlock) {
    lastSampleRate = sampleRate;
    totalSamplesProcessed = 0;
    midiQueue.clear();
}

double AetherAudioProcessor::getSyncTimeInMs() {
    if (auto* playHead = getPlayHead()) {
        if (auto position = playHead->getPosition()) {
            auto bpmOpt = position->getBpm();
            double bpm = bpmOpt ? *bpmOpt : 120.0;
            double quarterNoteMs = (60.0 / bpm) * 1000.0;
            double baseTime = quarterNoteMs;

            if (syncDivisionIndex == 0) return delayTimeMs;

            int div = (syncDivisionIndex - 1) % 6; 
            int type = (syncDivisionIndex - 1) / 6; 

            switch (div) {
                case 0: baseTime = quarterNoteMs * 4.0; break;   
                case 1: baseTime = quarterNoteMs * 2.0; break;   
                case 2: baseTime = quarterNoteMs; break;         
                case 3: baseTime = quarterNoteMs * 0.5; break;   
                case 4: baseTime = quarterNoteMs * 0.25; break;  
                case 5: baseTime = quarterNoteMs * 0.125; break; 
            }

            if (type == 1) baseTime *= 1.5;         
            else if (type == 2) baseTime *= (2.0/3.0); 

            return baseTime;                             
        }
    }
    return delayTimeMs;
}

void AetherAudioProcessor::processBlock (juce::AudioBuffer<float>& buffer, juce::MidiBuffer& midiMessages) {
    auto numSamples = buffer.getNumSamples();

    if (!isEnabled) {
        midiQueue.clear();
        totalSamplesProcessed += numSamples;
        return;
    }

    bool isPlaying = false;
    if (auto* ph = getPlayHead()) {
        if (auto pos = ph->getPosition()) {
            isPlaying = pos->getIsPlaying();
        }
    }

    if (killOnStop && !isPlaying) {
        midiQueue.clear();
        totalSamplesProcessed += numSamples;
        return; 
    }

    double currentDelayMs = (syncDivisionIndex == 0) ? delayTimeMs : getSyncTimeInMs();

    for (const auto metadata : midiMessages) {
        auto msg = metadata.getMessage();
        int localSamplePos = metadata.samplePosition;

        if (msg.isNoteOn()) {
            for (int i = 0; i < activeStepCount; ++i) {
                if (steps[i].muted) continue;
                if (random.nextInt(100) >= steps[i].probability) continue;

                double delayInSamples = (currentDelayMs * 0.001) * lastSampleRate * (i + 1);
                long long targetAbsSample = totalSamplesProcessed + localSamplePos + (long long)delayInSamples;

                auto delayedOn = msg;
                delayedOn.setNoteNumber(juce::jlimit(0, 127, msg.getNoteNumber() + steps[i].pitchOffset));
                delayedOn.setVelocity(steps[i].velocity / 127.0f);
                midiQueue.push_back({delayedOn, targetAbsSample});

                auto modMsg = juce::MidiMessage::controllerEvent(msg.getChannel(), 1, steps[i].modwheel);
                midiQueue.push_back({modMsg, targetAbsSample});

                auto delayedOff = juce::MidiMessage::noteOff(msg.getChannel(), delayedOn.getNoteNumber());
                midiQueue.push_back({delayedOff, targetAbsSample + (long long)(lastSampleRate * 0.15)});
            }
        }
    }

    for (auto it = midiQueue.begin(); it != midiQueue.end(); ) {
        if (it->targetSample >= totalSamplesProcessed && it->targetSample < totalSamplesProcessed + numSamples) {
            int localOffset = (int)(it->targetSample - totalSamplesProcessed);
            midiMessages.addEvent(it->message, localOffset);
            it = midiQueue.erase(it);
        } else if (it->targetSample < totalSamplesProcessed) {
            it = midiQueue.erase(it);
        } else {
            ++it;
        }
    }

    totalSamplesProcessed += numSamples;
    if (midiQueue.size() > 8192) midiQueue.erase(midiQueue.begin(), midiQueue.begin() + 4096);
}

void AetherAudioProcessor::getStateInformation (juce::MemoryBlock& destData) {
    juce::MemoryOutputStream stream(destData, true);
    stream.writeInt(2); // Increased version tag for reliability
    stream.writeBool(isEnabled);
    stream.writeDouble(delayTimeMs);
    stream.writeInt(syncDivisionIndex);
    stream.writeInt(activeStepCount);
    stream.writeBool(killOnStop);

    for (int i = 0; i < 16; ++i) {
        stream.writeInt(steps[i].pitchOffset);
        stream.writeInt(steps[i].velocity);
        stream.writeInt(steps[i].modwheel);
        stream.writeInt(steps[i].probability);
        stream.writeBool(steps[i].muted);
    }
}

void AetherAudioProcessor::setStateInformation (const void* data, int sizeInBytes) {
    juce::MemoryInputStream stream(data, static_cast<size_t>(sizeInBytes), false);
    int version = stream.readInt();
    if (version >= 1) { 
        isEnabled = stream.readBool();
        delayTimeMs = stream.readDouble();
        syncDivisionIndex = stream.readInt();
        activeStepCount = stream.readInt();
        killOnStop = stream.readBool();

        for (int i = 0; i < 16; ++i) {
            steps[i].pitchOffset = stream.readInt();
            steps[i].velocity = stream.readInt();
            steps[i].modwheel = stream.readInt();
            steps[i].probability = stream.readInt();
            steps[i].muted = stream.readBool();
        }
    }
}

juce::AudioProcessorEditor* AetherAudioProcessor::createEditor() { return new AetherAudioProcessorEditor (*this); }
juce::AudioProcessor* JUCE_CALLTYPE createPluginFilter() { return new AetherAudioProcessor(); }`;

const editorH = `// PluginEditor.h
#pragma once
#include "PluginProcessor.h"

class AetherLookAndFeel : public juce::LookAndFeel_V4 {
public:
    AetherLookAndFeel() {
        setColour(juce::ResizableWindow::backgroundColourId, juce::Colour(0xFF121212));
        setColour(juce::ComboBox::backgroundColourId, juce::Colour(0xFF121212));
        setColour(juce::ComboBox::outlineColourId, juce::Colour(0xFF00FF41));
        setColour(juce::ComboBox::textColourId, juce::Colour(0xFF00FF41));
        setColour(juce::Slider::thumbColourId, juce::Colour(0xFF00FF41));
        setColour(juce::Slider::trackColourId, juce::Colour(0xFF2A2A2A));
        setColour(juce::PopupMenu::backgroundColourId, juce::Colour(0xFF121212));
        setColour(juce::PopupMenu::textColourId, juce::Colour(0xFF00FF41));
        setColour(juce::PopupMenu::highlightedBackgroundColourId, juce::Colour(0xFF00FF41));
        setColour(juce::PopupMenu::highlightedTextColourId, juce::Colour(0xFF000000));
    }

    void drawRotarySlider (juce::Graphics& g, int x, int y, int width, int height,
                          float sliderPos, const float rotaryStartAngle, const float rotaryEndAngle,
                          juce::Slider& slider) override {
        auto radius = (float) juce::jmin (width / 2, height / 2) - 4.0f;
        auto centreX = (float) x + (float) width * 0.5f;
        auto centreY = (float) y + (float) height * 0.5f;
        auto angle = rotaryStartAngle + sliderPos * (rotaryEndAngle - rotaryStartAngle);

        g.setColour (juce::Colour(0xFF1A1A1A));
        g.fillEllipse (centreX - radius, centreY - radius, radius * 2, radius * 2);

        g.setColour (juce::Colour(0xFF00FF41).withAlpha(0.2f));
        g.drawEllipse (centreX - radius, centreY - radius, radius * 2, radius * 2, 1.0f);

        juce::Path p;
        p.addRectangle (-1.5f, -radius, 3.0f, radius * 0.8f);
        p.applyTransform (juce::AffineTransform::rotation (angle).translated (centreX, centreY));
        g.setColour (juce::Colour(0xFF00FF41));
        g.fillPath (p);
    }

    // Force the popup menu to always open downwards
    juce::PopupMenu::Options getOptionsForComboBoxMenu (juce::ComboBox& box, juce::Label& label) override
    {
        return juce::PopupMenu::Options().withTargetComponent (&box)
                                         .withItemThatMustBeVisible (box.getSelectedItemIndex())
                                         .withMinimumWidth (box.getWidth())
                                         .withMaximumNumColumns (1)
                                         .withStandardItemHeight (label.getHeight())
                                         .withPreferredPopupDirection (juce::PopupMenu::Options::PopupDirection::downwards);
    }

    int getMenuWindowFlags() override { return 0; }
};

class AetherAudioProcessorEditor : public juce::AudioProcessorEditor, private juce::Timer {
public:
    AetherAudioProcessorEditor (AetherAudioProcessor&);
    ~AetherAudioProcessorEditor() override;
    void paint (juce::Graphics&) override;
    void resized() override;
    void timerCallback() override;
    void mouseDown (const juce::MouseEvent& e) override;
    void mouseDrag (const juce::MouseEvent& e) override;
