const processorH = `// PluginProcessor.h
#pragma once
#include <JuceHeader.h>

struct DelayStep {
    int pitchOffset = 0;
    int velocity = 100;
    int modwheel = 0;
    int probability = 100;
    bool muted = false;
};

struct QueuedEvent {
    juce::MidiMessage message;
    long long targetSample;
};

class AetherAudioProcessor : public juce::AudioProcessor {
public:
    AetherAudioProcessor();
    ~AetherAudioProcessor() override;

    void prepareToPlay (double sampleRate, int samplesPerBlock) override;
    void releaseResources() override {}
    void processBlock (juce::AudioBuffer<float>&, juce::MidiBuffer&) override;

    juce::AudioProcessorEditor* createEditor() override;
    bool hasEditor() const override { return true; }

    const juce::String getName() const override { return "AETHER"; }
    bool acceptsMidi() const override { return true; }
    bool producesMidi() const override { return true; }
    double getTailLengthSeconds() const override { return 2.0; }

    int getNumPrograms() override { return 1; }
    int getCurrentProgram() override { return 0; }
    void setCurrentProgram (int) override {}
    const juce::String getProgramName (int) override { return {}; }
    void changeProgramName (int, const juce::String&) override {}

    void getStateInformation (juce::MemoryBlock& destData) override;
    void setStateInformation (const void* data, int sizeInBytes) override;

    // Public State - Accessed by Editor
    std::array<DelayStep, 16> steps;
    int activeStepCount = 16;
    double delayTimeMs = 500.0;
    int syncDivisionIndex = 3; 
    bool killOnStop = true;
    bool isEnabled = true;

private:
    double lastSampleRate = 44100.0;
    long long totalSamplesProcessed = 0;
    std::vector<QueuedEvent> midiQueue;
    juce::Random random;
    bool wasPlaying = false; 

    double getSyncTimeInMs();

    JUCE_DECLARE_NON_COPYABLE_WITH_LEAK_DETECTOR (AetherAudioProcessor)
};`;

const processorCpp = `// PluginProcessor.cpp
#include "PluginProcessor.h"
#include "PluginEditor.h"

AetherAudioProcessor::AetherAudioProcessor()
    : AudioProcessor (BusesProperties().withOutput ("Output", juce::AudioChannelSet::stereo(), true))
{
    isEnabled = true;
    delayTimeMs = 500.0;
    syncDivisionIndex = 3;
    activeStepCount = 16;
    killOnStop = true;

    for (int i = 0; i < 16; ++i) {
        steps[i].velocity = 127 - (i * 8);
        steps[i].modwheel = 0;
        steps[i].probability = 100;
        steps[i].pitchOffset = 0;
        steps[i].muted = false;
    }
}

AetherAudioProcessor::~AetherAudioProcessor() {}

void AetherAudioProcessor::prepareToPlay (double sampleRate, int samplesPerBlock) {
    lastSampleRate = sampleRate;
    totalSamplesProcessed = 0;
    midiQueue.clear();
    wasPlaying = false;
}

double AetherAudioProcessor::getSyncTimeInMs() {
    if (auto* playHead = getPlayHead()) {
        if (auto position = playHead->getPosition()) {
            auto bpmOpt = position->getBpm();
            double bpm = bpmOpt ? *bpmOpt : 120.0;
            double quarterNoteMs = (60.0 / bpm) * 1000.0;
            double baseTime = quarterNoteMs;

            if (syncDivisionIndex == 0) return delayTimeMs;

            int div = (syncDivisionIndex - 1) % 6; 
            int type = (syncDivisionIndex - 1) / 6; 

            switch (div) {
                case 0: baseTime = quarterNoteMs * 4.0; break;   
                case 1: baseTime = quarterNoteMs * 2.0; break;   
                case 2: baseTime = quarterNoteMs; break;         
                case 3: baseTime = quarterNoteMs * 0.5; break;   
                case 4: baseTime = quarterNoteMs * 0.25; break;  
                case 5: baseTime = quarterNoteMs * 0.125; break; 
            }

            if (type == 1) baseTime *= 1.5;         
            else if (type == 2) baseTime *= (2.0/3.0); 

            return baseTime;                             
        }
    }
    return delayTimeMs;
}

void AetherAudioProcessor::processBlock (juce::AudioBuffer<float>& buffer, juce::MidiBuffer& midiMessages) {
    auto numSamples = buffer.getNumSamples();

    bool isPlaying = false;
    if (auto* ph = getPlayHead()) {
        if (auto pos = ph->getPosition()) {
            isPlaying = pos->getIsPlaying();
        }
    }

    if (killOnStop && !isPlaying && wasPlaying) {
        for (int ch = 1; ch <= 16; ++ch) {
            midiMessages.addEvent(juce::MidiMessage::allNotesOff(ch), 0);
            midiMessages.addEvent(juce::MidiMessage::allSoundOff(ch), 0);
        }
        midiQueue.clear();
    }

    wasPlaying = isPlaying;

    if (!isEnabled || (killOnStop && !isPlaying)) {
        midiQueue.clear();
        totalSamplesProcessed += numSamples;
        return;
    }

    double currentDelayMs = (syncDivisionIndex == 0) ? delayTimeMs : getSyncTimeInMs();

    for (const auto metadata : midiMessages) {
        auto msg = metadata.getMessage();
        int localSamplePos = metadata.samplePosition;

        if (msg.isNoteOn()) {
            for (int i = 0; i < activeStepCount; ++i) {
                if (steps[i].muted) continue;
                if (random.nextInt(100) >= steps[i].probability) continue;

                double delayInSamples = (currentDelayMs * 0.001) * lastSampleRate * (i + 1);
                long long targetAbsSample = totalSamplesProcessed + localSamplePos + (long long)delayInSamples;

                auto delayedOn = msg;
                delayedOn.setNoteNumber(juce::jlimit(0, 127, msg.getNoteNumber() + steps[i].pitchOffset));
                delayedOn.setVelocity(steps[i].velocity / 127.0f);
                midiQueue.push_back({delayedOn, targetAbsSample});

                auto modMsg = juce::MidiMessage::controllerEvent(msg.getChannel(), 1, steps[i].modwheel);
                midiQueue.push_back({modMsg, targetAbsSample});

                auto delayedOff = juce::MidiMessage::noteOff(msg.getChannel(), delayedOn.getNoteNumber());
                midiQueue.push_back({delayedOff, targetAbsSample + (long long)(lastSampleRate * 0.15)});
            }
        }
    }

    for (auto it = midiQueue.begin(); it != midiQueue.end(); ) {
        if (it->targetSample >= totalSamplesProcessed && it->targetSample < totalSamplesProcessed + numSamples) {
            int localOffset = (int)(it->targetSample - totalSamplesProcessed);
            midiMessages.addEvent(it->message, localOffset);
            it = midiQueue.erase(it);
        } else if (it->targetSample < totalSamplesProcessed) {
            it = midiQueue.erase(it);
        } else {
            ++it;
        }
    }

    totalSamplesProcessed += numSamples;
    if (midiQueue.size() > 8192) midiQueue.erase(midiQueue.begin(), midiQueue.begin() + 4096);
}

void AetherAudioProcessor::getStateInformation (juce::MemoryBlock& destData) {
    juce::MemoryOutputStream stream(destData, true);
    stream.writeInt(2);
    stream.writeBool(isEnabled);
    stream.writeDouble(delayTimeMs);
    stream.writeInt(syncDivisionIndex);
    stream.writeInt(activeStepCount);
    stream.writeBool(killOnStop);

    for (int i = 0; i < 16; ++i) {
        stream.writeInt(steps[i].pitchOffset);
        stream.writeInt(steps[i].velocity);
        stream.writeInt(steps[i].modwheel);
        stream.writeInt(steps[i].probability);
        stream.writeBool(steps[i].muted);
    }
}

void AetherAudioProcessor::setStateInformation (const void* data, int sizeInBytes) {
    juce::MemoryInputStream stream(data, static_cast<size_t>(sizeInBytes), false);
    int version = stream.readInt();
    if (version >= 1) { 
        isEnabled = stream.readBool();
        delayTimeMs = stream.readDouble();
        syncDivisionIndex = stream.readInt();
        activeStepCount = stream.readInt();
        killOnStop = stream.readBool();

        for (int i = 0; i < 16; ++i) {
            steps[i].pitchOffset = stream.readInt();
            steps[i].velocity = stream.readInt();
            steps[i].modwheel = stream.readInt();
            steps[i].probability = stream.readInt();
            steps[i].muted = stream.readBool();
        }
    }
}

juce::AudioProcessorEditor* AetherAudioProcessor::createEditor() { return new AetherAudioProcessorEditor (*this); }
juce::AudioProcessor* JUCE_CALLTYPE createPluginFilter() { return new AetherAudioProcessor(); }`;

