    AetherAudioProcessor& audioProcessor;
    juce::ComboBox syncMenu;
    juce::Slider timeSlider;
    int activeDraggingLaneIndex = -1;

    struct Lane { juce::String label; int min, max; bool isBipolar; juce::String propertyId; };
    std::vector<Lane> lanes { 
        {"Pitch Shift", -24, 24, true, "pitch"}, 
        {"Velocity", 1, 127, false, "velocity"}, 
        {"Modwheel", 0, 127, false, "modwheel"}, 
        {"Probability", 0, 100, false, "probability"}, 
