              >
                <span className="crt-glow">{state.syncDivision === 'ms' ? 'MILLISEC (ms)' : state.syncDivision}</span>
                <span className="ml-2 text-[8px] transform transition-transform text-[#00ff41]" style={{ transform: isDropdownOpen ? 'rotate(180deg)' : 'rotate(0deg)' }}>▼</span>
