#include "PluginProcessor.h"
#include "PluginEditor.h"

AetherAudioProcessorEditor::AetherAudioProcessorEditor (AetherAudioProcessor& p)
    : AudioProcessorEditor (&p), audioProcessor (p)
{
    setLookAndFeel(&lookAndFeel);

    syncMenu.setJustificationType(juce::Justification::centredLeft);
    syncMenu.addItem("ms", 1);
    const juce::StringArray divs = {"1/1", "1/2", "1/4", "1/8", "1/16", "1/32"};
    for (int i=0; i<divs.size(); ++i) syncMenu.addItem(divs[i], i+2);
    for (int i=0; i<divs.size(); ++i) syncMenu.addItem(divs[i]+"d", i+8);
    for (int i=0; i<divs.size(); ++i) syncMenu.addItem(divs[i]+"t", i+14);

    syncMenu.onChange = [this] { audioProcessor.syncDivisionIndex = syncMenu.getSelectedItemIndex(); };
    syncMenu.setSelectedItemIndex(audioProcessor.syncDivisionIndex, juce::dontSendNotification);
    addAndMakeVisible(syncMenu);

    timeSlider.setSliderStyle(juce::Slider::RotaryVerticalDrag);
    timeSlider.setRange(1.0, 2000.0, 1.0);
    timeSlider.setTextBoxStyle(juce::Slider::NoTextBox, false, 0, 0);
    timeSlider.onValueChange = [this] { audioProcessor.delayTimeMs = timeSlider.getValue(); };
    timeSlider.setValue(audioProcessor.delayTimeMs, juce::dontSendNotification);
    addAndMakeVisible(timeSlider);

    // Narrowed width (1040) for 15 steps
    setSize (1040, 1000); 
    startTimerHz(30);
}

AetherAudioProcessorEditor::~AetherAudioProcessorEditor() { setLookAndFeel(nullptr); }

void AetherAudioProcessorEditor::timerCallback() {
    timeSlider.setVisible(audioProcessor.syncDivisionIndex == 0);

    if (syncMenu.getSelectedItemIndex() != audioProcessor.syncDivisionIndex)
        syncMenu.setSelectedItemIndex(audioProcessor.syncDivisionIndex, juce::dontSendNotification);

    if (audioProcessor.syncDivisionIndex == 0 && !timeSlider.isMouseButtonDown())
    {
        if (std::abs(timeSlider.getValue() - audioProcessor.delayTimeMs) > 0.01)
            timeSlider.setValue(audioProcessor.delayTimeMs, juce::dontSendNotification);
    }

    repaint();
}

void AetherAudioProcessorEditor::drawDice(juce::Graphics& g, int x, int y, int size) {
    g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.6f));
    g.drawRect(x, y, size, size, 2); 
    float ds = size * 0.15f;
    g.fillEllipse(x + size*0.2, y + size*0.2, ds, ds);
    g.fillEllipse(x + size*0.7, y + size*0.2, ds, ds);
    g.fillEllipse(x + size*0.45, y + size*0.45, ds, ds);
    g.fillEllipse(x + size*0.2, y + size*0.7, ds, ds);
    g.fillEllipse(x + size*0.7, y + size*0.7, ds, ds);
}

void AetherAudioProcessorEditor::handleLaneInteraction(const juce::MouseEvent& e, bool isClick) {
    int laneStartY = 200; int spacing = 150;

    juce::Rectangle<int> powerArea(40, 40, 50, 50);
    if (isClick && powerArea.contains(e.x, e.y)) { audioProcessor.isEnabled = !audioProcessor.isEnabled; repaint(); return; }

    juce::Rectangle<int> killArea(550, 60, 130, 40);
    if (isClick && killArea.contains(e.x, e.y)) { audioProcessor.killOnStop = !audioProcessor.killOnStop; repaint(); return; }

    if (activeDraggingLaneIndex != -1 && !isClick) {
        int l = activeDraggingLaneIndex; int curY = laneStartY + (l * spacing);
        float sw = 950.0f / 15.0f; // Adjusted for 15 steps and 950 width
        int idx = juce::jlimit(0, 14, (int)((e.x - 40) / sw));
        auto& s = audioProcessor.steps[idx]; auto& lane = lanes[l];
        if (lane.propertyId != "muted") {
            float normY = 1.0f - (float)(e.y - curY) / 80.0f; normY = juce::jlimit(0.0f, 1.0f, normY);
            int val = (int)(lane.min + normY * (lane.max - lane.min));
            if (lane.propertyId == "pitch") s.pitchOffset = val;
            else if (lane.propertyId == "velocity") s.velocity = val;
            else if (lane.propertyId == "modwheel") s.modwheel = val;
            else if (lane.propertyId == "probability") s.probability = val;
            repaint();
        }
        return;
    }

    for (int l = 0; l < (int)lanes.size(); ++l) {
        int curY = laneStartY + (l * spacing);
        juce::Rectangle<int> diceArea(40, curY - 30, 24, 24);
        if (isClick && diceArea.contains(e.x, e.y)) {
            juce::Random r; auto& lane = lanes[l];
            for(auto& s : audioProcessor.steps) {
                if (lane.propertyId == "pitch") s.pitchOffset = r.nextInt(juce::Range<int>(-24, 25));
                else if (lane.propertyId == "velocity") s.velocity = r.nextInt(juce::Range<int>(1, 128));
                else if (lane.propertyId == "modwheel") s.modwheel = r.nextInt(juce::Range<int>(0, 128));
                else if (lane.propertyId == "probability") s.probability = r.nextInt(juce::Range<int>(0, 101));
                else if (lane.propertyId == "muted") s.muted = r.nextBool();
            }
            repaint(); return;
        }
        juce::Rectangle<int> laneArea(40, curY, 950, 100); 
        if (laneArea.contains(e.x, e.y)) {
            activeDraggingLaneIndex = l;
            float sw = 950.0f / 15.0f; int idx = juce::jlimit(0, 14, (int)((e.x - 40) / sw));
            auto& s = audioProcessor.steps[idx]; auto& lane = lanes[l];
            if (lane.propertyId == "muted") { if (isClick) s.muted = !s.muted; }
            else {
                float normY = 1.0f - (float)(e.y - curY) / 80.0f; normY = juce::jlimit(0.0f, 1.0f, normY);
                int val = (int)(lane.min + normY * (lane.max - lane.min));
                if (lane.propertyId == "pitch") s.pitchOffset = val;
                else if (lane.propertyId == "velocity") s.velocity = val;
                else if (lane.propertyId == "modwheel") s.modwheel = val;
                else if (lane.propertyId == "probability") s.probability = val;
            }
            repaint(); return;
        }
    }
    juce::Rectangle<int> scArea(40, 930, 950, 30);
    if (scArea.contains(e.x, e.y)) {
        float nx = (float)(e.x - 40) / 950.0f;
        audioProcessor.activeStepCount = juce::jlimit(1, 15, (int)std::ceil(nx * 15.0f)); repaint();
    }
}

void AetherAudioProcessorEditor::mouseDown (const juce::MouseEvent& e) { handleLaneInteraction(e, true); }
void AetherAudioProcessorEditor::mouseDrag (const juce::MouseEvent& e) { handleLaneInteraction(e, false); }
void AetherAudioProcessorEditor::mouseUp (const juce::MouseEvent& e) { activeDraggingLaneIndex = -1; }

void AetherAudioProcessorEditor::paint (juce::Graphics& g) {
    g.fillAll (juce::Colour(0xFF121212));
    if (!audioProcessor.isEnabled) g.setOpacity(0.4f);

    // Header
    g.setColour(juce::Colour(0xFF00FF41));
    g.drawEllipse(40, 40, 50, 50, 2);
    if (audioProcessor.isEnabled) { g.fillEllipse(50, 50, 30, 30); g.setColour(juce::Colour(0xFF000000)); g.drawText("I", 50, 50, 30, 30, juce::Justification::centred); }
    else { g.drawText("O", 50, 50, 30, 30, juce::Justification::centred); }

    juce::Rectangle<int> killArea(550, 60, 130, 40);
    if (audioProcessor.killOnStop) {
        g.setColour(juce::Colour(0xFF00FF41)); g.fillRect(killArea);
        g.setColour(juce::Colour(0xFF000000));
    } else {
        g.setColour(juce::Colour(0xFF00FF41)); g.drawRect(killArea, 2);
    }
    g.setFont(juce::Font("IBM Plex Mono", 14.0f, juce::Font::bold));
    g.drawText("KILL ON STOP", killArea, juce::Justification::centred);

    g.setColour(juce::Colour(0xFF00FF41));
    g.setFont(juce::Font("IBM Plex Mono", 64.0f, juce::Font::bold));
    g.drawText("AETHER", 110, 30, 400, 70, juce::Justification::left);
    g.setFont(14.0f); g.setOpacity(0.6f);
    g.drawText("Polyphonic MIDI Delay", 115, 95, 400, 20, juce::Justification::left);

    g.setFont(10.0f); g.setOpacity(0.8f);
    g.drawText("DELAY TIME", 850, 40, 150, 15, juce::Justification::left);
    if (audioProcessor.syncDivisionIndex == 0) {
        g.drawText("TIME (MS)", 750, 35, 80, 15, juce::Justification::centred);
        g.setFont(12.0f);
        g.drawText(juce::String(audioProcessor.delayTimeMs, 0) + " ms", 750, 115, 80, 20, juce::Justification::centred);
    }

    int laneStartY = 200; int spacing = 150;
    for (int l = 0; l < (int)lanes.size(); ++l) {
        int laneY = laneStartY + (l * spacing); auto& lane = lanes[l];
        drawDice(g, 40, laneY - 28, 20);
        g.setOpacity(0.8f); g.setFont(juce::Font("IBM Plex Mono", 18.0f, juce::Font::bold));
        g.drawText(lane.label.toUpperCase(), 75, laneY - 30, 200, 25, juce::Justification::left);
        float sw = 950.0f / 15.0f; int bh = 80;
        for (int i = 0; i < 15; ++i) {
            auto& s = audioProcessor.steps[i]; float op = (i >= audioProcessor.activeStepCount) ? 0.2f : 1.0f;
            g.setColour(juce::Colour(0xFF121212)); 
            g.fillRect(40.0f + i * sw + (sw * 0.1f), (float)laneY, sw * 0.8f, (float)bh);
            g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.3f * op));
            g.drawRect(40.0f + i * sw + (sw * 0.1f), (float)laneY, sw * 0.8f, (float)bh, 1.0f);

            g.setColour(juce::Colour(0xFF00FF41).withAlpha(op));
            int val = 0; juce::String vs = "";
            if (lane.propertyId == "pitch") { val = s.pitchOffset; vs = (val > 0 ? "+" : "") + juce::String(val); }
            else if (lane.propertyId == "velocity") { val = s.velocity; vs = juce::String(val); }
            else if (lane.propertyId == "modwheel") { val = s.modwheel; vs = juce::String(val); }
            else if (lane.propertyId == "probability") { val = s.probability; vs = juce::String(val) + "%"; }

            if (lane.propertyId == "muted") {
                juce::Rectangle<float> mb(40.0f + i * sw + 8, (float)laneY + 8, sw - 16, (float)bh - 16);
                if (!s.muted) { g.fillRect(mb); g.setColour(juce::Colour(0xFF000000)); g.fillEllipse(mb.getCentreX()-3, mb.getCentreY()-3, 6, 6); }
                else { g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.1f * op)); g.drawRect(mb, 1.0f); }
            } else if (lane.isBipolar) {
                float hh = bh / 2.0f; float h = (std::abs((float)val) / (float)lane.max) * hh;
                if (val >= 0) g.fillRect(40.0f + i * sw + (sw * 0.1f), (float)laneY + hh - h, sw * 0.8f, h);
                else g.fillRect(40.0f + i * sw + (sw * 0.1f), (float)laneY + hh, sw * 0.8f, h);
            } else {
                float h = ((float)(val - lane.min) / (float)(lane.max - lane.min)) * bh;
                g.fillRect(40.0f + i * sw + (sw * 0.1f), (float)laneY + (bh - h), sw * 0.8f, h);
            }
            if (lane.propertyId != "muted") {
                g.setColour(juce::Colour(0xFF00FF41).withAlpha(op)); 
                g.setFont(juce::Font("IBM Plex Mono", 16.5f, juce::Font::bold));
                g.drawText(vs, (int)(40.0f + i * sw), laneY + bh + 4, (int)sw, 24, juce::Justification::centred);
            }
        }
    }

    g.setOpacity(1.0f); g.setColour(juce::Colour(0xFF00FF41)); g.setFont(juce::Font("IBM Plex Mono", 14.0f, juce::Font::bold));
    g.drawText("STEP COUNT: " + juce::String(audioProcessor.activeStepCount), 40, 910, 400, 20, juce::Justification::left);

    float sew = 950.0f / 15.0f;
    for (int i = 0; i < 15; ++i) {
        juce::Rectangle<float> seg(40.0f + i * sew + 1, 935, sew - 2, 25);
        bool isActive = (i < audioProcessor.activeStepCount);
        g.setColour(isActive ? juce::Colour(0xFF00FF41) : juce::Colour(0xFF003311));
        g.fillRect(seg); 
        g.setColour(isActive ? juce::Colour(0xFF00FF41).withAlpha(0.4f) : juce::Colour(0xFF004411));
        g.drawRect(seg, 1.0f);
    }
}

void AetherAudioProcessorEditor::resized() {
    syncMenu.setBounds(850, 60, 150, 30);
    timeSlider.setBounds(750, 45, 80, 80);
}
