const editorCpp = `// PluginEditor.cpp
#include "PluginProcessor.h"
#include "PluginEditor.h"

AetherAudioProcessorEditor::AetherAudioProcessorEditor (AetherAudioProcessor& p)
    : AudioProcessorEditor (&p), audioProcessor (p)
{
    setLookAndFeel(&lookAndFeel);

    const juce::StringArray names = {
        "1/1", "1/2", "1/4", "1/8", "1/16", "1/32",
        "1/1d", "1/2d", "1/4d", "1/8d", "1/16d", "1/32d",
        "1/1t", "1/2t", "1/4t", "1/8t", "1/16t", "1/32t"
    };

    for (int i = 0; i < names.size(); ++i) {
        auto* b = radioButtons.emplace_back(std::make_unique<juce::TextButton>(names[i])).get();
        b->setRadioGroupId(101);
        b->setClickingTogglesState(true);
        b->onClick = [this, i] { audioProcessor.syncDivisionIndex = i + 1; repaint(); };
        addAndMakeVisible(b);
    }

    msButton.setButtonText("MANUAL (MS)");
    msButton.setRadioGroupId(101);
    msButton.setClickingTogglesState(true);
    msButton.onClick = [this] { audioProcessor.syncDivisionIndex = 0; repaint(); };
    addAndMakeVisible(msButton);

    killOnStopButton.setButtonText("KILL ON STOP");
    killOnStopButton.setClickingTogglesState(true);
    killOnStopButton.onClick = [this] {
        auto* p = audioProcessor.apvts.getParameter("killOnStop");
        p->setValueNotifyingHost(killOnStopButton.getToggleState() ? 1.0f : 0.0f);
        repaint();
    };
    addAndMakeVisible(killOnStopButton);

    setSize (1040, 1000); 
    startTimerHz(30);
}

AetherAudioProcessorEditor::~AetherAudioProcessorEditor() { setLookAndFeel(nullptr); }

void AetherAudioProcessorEditor::timerCallback() {
    if (audioProcessor.syncDivisionIndex == 0) {
        if (!msButton.getToggleState()) msButton.setToggleState(true, juce::dontSendNotification);
    } else {
        int idx = audioProcessor.syncDivisionIndex - 1;
        if (idx >= 0 && idx < (int)radioButtons.size()) {
            if (!radioButtons[idx]->getToggleState()) radioButtons[idx]->setToggleState(true, juce::dontSendNotification);
        }
    }

    bool k = *audioProcessor.apvts.getRawParameterValue("killOnStop");
    if (killOnStopButton.getToggleState() != k) killOnStopButton.setToggleState(k, juce::dontSendNotification);

    repaint();
}

void AetherAudioProcessorEditor::drawDice(juce::Graphics& g, int x, int y, int size, bool isPressed) {
    auto green = juce::Colour(0xFF00FF41);
    if (isPressed) { g.setColour(green); g.fillRect(x, y, size, size); g.setColour(juce::Colour(0xFF000000)); }
    else { g.setColour(green.withAlpha(0.6f)); g.drawRect(x, y, size, size, 2); }
    float ds = size * 0.15f;
    g.fillEllipse(x + size*0.2, y + size*0.2, ds, ds); g.fillEllipse(x + size*0.7, y + size*0.2, ds, ds);
    g.fillEllipse(x + size*0.45, y + size*0.45, ds, ds); g.fillEllipse(x + size*0.2, y + size*0.7, ds, ds);
    g.fillEllipse(x + size*0.7, y + size*0.7, ds, ds);
}

void AetherAudioProcessorEditor::drawReset(juce::Graphics& g, int x, int y, int size, bool isPressed) {
    auto green = juce::Colour(0xFF00FF41);
    if (isPressed) { g.setColour(green); g.fillRect(x, y, size, size); g.setColour(juce::Colour(0xFF000000)); }
    else { g.setColour(green.withAlpha(0.6f)); g.drawRect(x, y, size, size, 2); }
    g.setFont(juce::Font(size * 0.8f, juce::Font::bold)); g.drawText("R", x, y, size, size, juce::Justification::centred);
}

void AetherAudioProcessorEditor::handleInteraction(const juce::MouseEvent& e, bool isClick) {
    int laneStartY = 200, spacing = 150;
    int startX = 610; 
    int gridWidth = 6 * 62;
    juce::Rectangle<int> msBoxRect(startX + gridWidth - 68, 135, 68, 42);

    if (audioProcessor.syncDivisionIndex == 0) {
        if (isClick && msBoxRect.contains(e.x, e.y)) {
            draggingMsBox = true; dragStartMsVal = *audioProcessor.apvts.getRawParameterValue("delayTimeMs");
            return;
        }
        if (draggingMsBox && !isClick) {
            float delta = (float)e.getDistanceFromDragStartY() * -0.5f;
            float newVal = juce::jlimit(1.0f, 2000.0f, dragStartMsVal + delta);
            audioProcessor.apvts.getParameter("delayTimeMs")->setValueNotifyingHost(audioProcessor.apvts.getParameter("delayTimeMs")->getNormalisableRange().convertTo0to1(newVal));
            repaint(); return;
        }
    }
    if (isClick && juce::Rectangle<int>(40, 40, 50, 50).contains(e.x, e.y)) {
        auto* p = audioProcessor.apvts.getParameter("enabled");
        p->setValueNotifyingHost(p->getValue() > 0.5f ? 0.0f : 1.0f); repaint(); return;
    }
    if (draggingLaneIdx != -1 && !isClick) {
        int l = draggingLaneIdx, curY = laneStartY + (l * spacing);
        float sw = 950.0f / 15.0f; int idx = juce::jlimit(0, 14, (int)((e.x - 40) / sw));
        auto& s = audioProcessor.steps[idx]; auto& lane = lanes[l];
        if (lane.propertyId != "muted") {
            float nY = 1.0f - (float)(e.y - curY) / 80.0f; nY = juce::jlimit(0.0f, 1.0f, nY);
            int val = (int)(lane.min + nY * (lane.max - lane.min));
            if (lane.propertyId == "pitch") s.pitchOffset = val; else if (lane.propertyId == "velocity") s.velocity = val;
            else if (lane.propertyId == "modwheel") s.modwheel = val; else if (lane.propertyId == "probability") s.probability = val;
            repaint();
        }
        return;
    }
    for (int l = 0; l < (int)lanes.size(); ++l) {
        int curY = laneStartY + (l * spacing);
        if (isClick && juce::Rectangle<int>(40, curY - 30, 24, 24).contains(e.x, e.y)) {
            pressedDiceIdx = l; repaint(); juce::Random r; auto& lane = lanes[l];
            for(auto& s : audioProcessor.steps) {
                if (lane.propertyId == "pitch") s.pitchOffset = r.nextInt(juce::Range<int>(-24, 25));
                else if (lane.propertyId == "velocity") s.velocity = r.nextInt(juce::Range<int>(1, 128));
                else if (lane.propertyId == "modwheel") s.modwheel = r.nextInt(juce::Range<int>(0, 128));
                else if (lane.propertyId == "probability") s.probability = r.nextInt(juce::Range<int>(0, 101));
                else if (lane.propertyId == "muted") s.muted = r.nextBool();
            }
            return;
        }
        if (isClick && juce::Rectangle<int>(70, curY - 30, 24, 24).contains(e.x, e.y)) {
            pressedResetIdx = l; repaint(); auto& lane = lanes[l];
            for(int i=0; i<15; ++i) {
                auto& s = audioProcessor.steps[i];
                if (lane.propertyId == "pitch") s.pitchOffset = 0;
                else if (lane.propertyId == "velocity") s.velocity = (int)(127 - (i * (126.0/14.0)));
                else if (lane.propertyId == "modwheel") s.modwheel = 0;
                else if (lane.propertyId == "probability") s.probability = 100;
                else if (lane.propertyId == "muted") s.muted = false;
            }
            return;
        }
        if (juce::Rectangle<int>(40, curY, 950, 100).contains(e.x, e.y)) {
            draggingLaneIdx = l; float sw = 950.0f / 15.0f; int idx = juce::jlimit(0, 14, (int)((e.x - 40) / sw));
            auto& s = audioProcessor.steps[idx]; auto& lane = lanes[l];
            if (lane.propertyId == "muted") { if (isClick) { s.muted = !s.muted; repaint(); } }
            else {
                float nY = 1.0f - (float)(e.y - curY) / 80.0f; nY = juce::jlimit(0.0f, 1.0f, nY);
                int val = (int)(lane.min + nY * (lane.max - lane.min));
                if (lane.propertyId == "pitch") s.pitchOffset = val; else if (lane.propertyId == "velocity") s.velocity = val;
                else if (lane.propertyId == "modwheel") s.modwheel = val; else if (lane.propertyId == "probability") s.probability = val;
                repaint();
            }
            return;
        }
    }
    if (juce::Rectangle<int>(40, 930, 950, 30).contains(e.x, e.y)) {
        float n = (float)(e.x - 40) / 950.0f; audioProcessor.apvts.getParameter("stepCount")->setValueNotifyingHost(n);
        repaint();
    }
}

void AetherAudioProcessorEditor::mouseDown (const juce::MouseEvent& e) { handleInteraction(e, true); }
void AetherAudioProcessorEditor::mouseDrag (const juce::MouseEvent& e) { handleInteraction(e, false); }
void AetherAudioProcessorEditor::mouseUp (const juce::MouseEvent& e) { 
    draggingLaneIdx = -1; pressedDiceIdx = -1; pressedResetIdx = -1; draggingMsBox = false; repaint();
}

void AetherAudioProcessorEditor::paint (juce::Graphics& g) {
    bool en = *audioProcessor.apvts.getRawParameterValue("enabled");
    int scCount = (int)*audioProcessor.apvts.getRawParameterValue("stepCount");
    float tmVal = *audioProcessor.apvts.getRawParameterValue("delayTimeMs");

    g.fillAll (juce::Colour(0xFF121212)); 
    if (!en) g.setOpacity(0.4f);

    // Power
    g.setColour(juce::Colour(0xFF00FF41));
    g.drawEllipse(40, 40, 50, 50, 2);
    if (en) { g.fillEllipse(50, 50, 30, 30); g.setColour(juce::Colour(0xFF000000)); g.drawText("I", 50, 50, 30, 30, juce::Justification::centred); }
    else { g.drawText("O", 50, 50, 30, 30, juce::Justification::centred); }

    // Logo
    g.setColour(juce::Colour(0xFF00FF41)); g.setFont(juce::Font("IBM Plex Mono", 64.0f, juce::Font::bold));
    g.drawText("AETHER", 110, 30, 400, 70, juce::Justification::left);
    g.setFont(14.0f); g.setOpacity(0.6f); g.drawText("Polyphonic MIDI Delay", 115, 95, 400, 20, juce::Justification::left);

    g.setFont(juce::Font("IBM Plex Mono", 10.0f, juce::Font::bold)); g.setOpacity(0.6f);
    g.drawText("DELAY TIME MATRIX", 610, 20, 200, 15, juce::Justification::left);

    // MS Value Box
    int startX = 610; 
    int gridWidth = 6 * 62;
    juce::Rectangle<int> msBox(startX + gridWidth - 68, 135, 68, 42);

    bool isMsMode = (audioProcessor.syncDivisionIndex == 0);
    g.setOpacity(isMsMode ? 1.0f : 0.20f);
    g.setColour(juce::Colour(0xFF1A1A1A)); g.fillRect(msBox);
    g.setColour(juce::Colour(0xFF00FF41)); g.drawRect(msBox, 2);
    g.setFont(juce::Font("IBM Plex Mono", 20.0f, juce::Font::bold));
    g.drawText(juce::String((int)tmVal), msBox, juce::Justification::centred);
    g.setOpacity(1.0f);

    // Lanes
    int laneStartY = 200, spacing = 150;
    for (int l = 0; l < (int)lanes.size(); ++l) {
        int lY = laneStartY + (l * spacing); auto& lane = lanes[l];
        drawDice(g, 40, lY - 28, 20, pressedDiceIdx == l);
        drawReset(g, 70, lY - 28, 20, pressedResetIdx == l);
        g.setOpacity(0.8f); g.setColour(juce::Colour(0xFF00FF41)); g.setFont(juce::Font("IBM Plex Mono", 18.0f, juce::Font::bold));
        g.drawText(lane.label.toUpperCase(), 105, lY - 30, 200, 25, juce::Justification::left);
        float sw = 950.0f / 15.0f; int bh = 80;
        for (int i = 0; i < 15; ++i) {
            auto& s = audioProcessor.steps[i]; float op = (i >= scCount) ? 0.2f : 1.0f;
            g.setColour(juce::Colour(0xFF121212)); g.fillRect(40.0f + i * sw + (sw * 0.1f), (float)lY, sw * 0.8f, (float)bh);
            g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.3f * op)); g.drawRect(40.0f + i * sw + (sw * 0.1f), (float)lY, sw * 0.8f, (float)bh, 1.0f);
            g.setColour(juce::Colour(0xFF00FF41).withAlpha(op));
            int val = 0; juce::String vs = "";
            if (lane.propertyId == "pitch") { val = s.pitchOffset; vs = (val > 0 ? "+" : "") + juce::String(val); }
            else if (lane.propertyId == "velocity") { val = s.velocity; vs = juce::String(val); }
            else if (lane.propertyId == "modwheel") { val = s.modwheel; vs = juce::String(val); }
            else if (lane.propertyId == "probability") { val = s.probability; vs = juce::String(val) + "%"; }
            if (lane.propertyId == "muted") {
                juce::Rectangle<float> mb(40.0f + i * sw + 8, (float)lY + 8, sw - 16, (float)bh - 16);
                if (!s.muted) { g.fillRect(mb); g.setColour(juce::Colour(0xFF000000)); g.fillEllipse(mb.getCentreX()-3, mb.getCentreY()-3, 6, 6); }
                else { g.setColour(juce::Colour(0xFF00FF41).withAlpha(0.1f * op)); g.drawRect(mb, 1.0f); }
            } else if (lane.isBipolar) {
                float hh = bh / 2.0f; float h = (std::abs((float)val) / (float)lane.max) * hh;
                if (val >= 0) g.fillRect(40.0f + i * sw + (sw * 0.1f), (float)lY + hh - h, sw * 0.8f, h);
                else g.fillRect(40.0f + i * sw + (sw * 0.1f), (float)lY + hh, sw * 0.8f, h);
            } else {
                float h = ((float)(val - lane.min) / (float)(lane.max - lane.min)) * bh;
                g.fillRect(40.0f + i * sw + (sw * 0.1f), (float)lY + (bh - h), sw * 0.8f, h);
            }
            if (lane.propertyId != "muted") {
                g.setColour(juce::Colour(0xFF00FF41).withAlpha(op)); g.setFont(juce::Font("IBM Plex Mono", 16.5f, juce::Font::bold));
                g.drawText(vs, (int)(40.0f + i * sw), lY + bh + 4, (int)sw, 24, juce::Justification::centred);
            }
        }
    }

    // Step Count
    g.setOpacity(1.0f); g.setColour(juce::Colour(0xFF00FF41)); g.setFont(juce::Font("IBM Plex Mono", 14.0f, juce::Font::bold));
    g.drawText("STEP COUNT: " + juce::String(scCount), 40, 910, 400, 20, juce::Justification::left);
    float sew = 950.0f / 15.0f;
    for (int i = 0; i < 15; ++i) {
        juce::Rectangle<float> seg(40.0f + i * sew + 1, 935, sew - 2, 25);
        bool isActive = (i < scCount); g.setColour(isActive ? juce::Colour(0xFF00FF41) : juce::Colour(0xFF003311));
        g.fillRect(seg); g.setColour(isActive ? juce::Colour(0xFF00FF41).withAlpha(0.4f) : juce::Colour(0xFF004411)); g.drawRect(seg, 1.0f);
    }

    // --- POST FX LAYER (CRT) ---
    g.setOpacity(1.0f);
    auto b = getLocalBounds();
    // Scanlines
    g.setColour(juce::Colour(0x0A000000));
    for (int y = 0; y < getHeight(); y += 4) {
        g.fillRect(0, y, getWidth(), 2);
    }
    // Vignette
    juce::ColourGradient vignette(juce::Colours::transparentBlack, b.getCentreX(), b.getCentreY(), juce::Colours::black.withAlpha(0.3f), 0, 0, true);
    g.setGradientFill(vignette);
    g.fillRect(b);
}

void AetherAudioProcessorEditor::resized() {
    int startX = 610, startY = 40, w = 62, h = 28, gap = 0;
    for (int i = 0; i < 18; ++i) {
        int col = i % 6;
        int row = i / 6;
        radioButtons[i]->setBounds(startX + col * (w + gap), startY + row * (h + gap), w, h);
    }
    int gridWidth = 6 * w;

    // Aligned to the bottom of the matrix
    killOnStopButton.setBounds(startX, 135, 120, 42);
    msButton.setBounds(startX + 120 + 4, 135, gridWidth - 120 - 4 - 72, 42);
}
`;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { INITIAL_STATE, PluginState, Step } from './types';
import { StepLane } from './components/StepLane';
import { CodeExporter } from './components/CodeExporter';

const SYNC_STRAIGHT = ['1/1', '1/2', '1/4', '1/8', '1/16', '1/32'];
const SYNC_DOTTED = ['1/1d', '1/2d', '1/4d', '1/8d', '1/16d', '1/32d'];
const SYNC_TRIPLET = ['1/1t', '1/2t', '1/4t', '1/8t', '1/16t', '1/32t'];

export const App: React.FC = () => {
  const [state, setState] = useState<PluginState>(INITIAL_STATE);
  const [isExporterOpen, setIsExporterOpen] = useState(false);
  const stepCountRef = useRef<HTMLDivElement>(null);
  const isDraggingStepCount = useRef(false);

  // Value Box dragging state
  const isDraggingMs = useRef(false);
  const startY = useRef(0);
  const startMsVal = useRef(0);

  const updateStep = useCallback((index: number, value: number | boolean, property: keyof Step) => {
    setState(prev => {
      const newSteps = [...prev.steps];
      newSteps[index] = { ...newSteps[index], [property]: value };
      return { ...prev, steps: newSteps };
    });
  }, []);

  const randomizeLane = useCallback((property: keyof Step, min: number, max: number) => {
    setState(prev => {
      const newSteps = prev.steps.map(step => {
        let newVal: any;
        if (property === 'muted') {
          newVal = Math.random() > 0.5;
        } else {
          newVal = Math.round(min + Math.random() * (max - min));
        }
        return { ...step, [property]: newVal };
      });
      return { ...prev, steps: newSteps };
    });
  }, []);

  const resetLane = useCallback((property: keyof Step) => {
    setState(prev => {
      const newSteps = prev.steps.map((step, i) => {
        let defaultVal: any;
        switch(property) {
          case 'pitch': defaultVal = 0; break;
          case 'velocity': defaultVal = Math.round(127 - (i * (126 / 14))); break;
          case 'modwheel': defaultVal = 0; break;
          case 'probability': defaultVal = 100; break;
          case 'muted': defaultVal = false; break;
          default: defaultVal = 0;
        }
        return { ...step, [property]: defaultVal };
      });
      return { ...prev, steps: newSteps };
    });
  }, []);

  const handleStepCountInteraction = (clientX: number) => {
    if (!stepCountRef.current) return;
    const rect = stepCountRef.current.getBoundingClientRect();
    const width = rect.width;
    const relativeX = Math.max(0, Math.min(width, clientX - rect.left));
    const normalized = relativeX / width;
    const newCount = Math.max(1, Math.min(15, Math.ceil(normalized * 15)));
    setState(prev => ({ ...prev, stepCount: newCount }));
  };

  const onStepCountMouseDown = (e: React.MouseEvent) => {
    isDraggingStepCount.current = true;
    handleStepCountInteraction(e.clientX);
  };

  const handleMsDrag = useCallback((clientY: number) => {
    if (!isDraggingMs.current) return;
    const deltaY = startY.current - clientY;
    const sensitivity = 0.5; 
    const newVal = Math.max(1, Math.min(2000, Math.round(startMsVal.current + (deltaY * sensitivity))));
    setState(prev => ({ ...prev, delayTimeMs: newVal }));
  }, []);

  const onMsMouseDown = (e: React.MouseEvent) => {
    if (state.syncDivision !== 'ms') return;
    isDraggingMs.current = true;
    startY.current = e.clientY;
    startMsVal.current = state.delayTimeMs;
    document.body.style.cursor = 'ns-resize';
  };

  useEffect(() => {
    const handleGlobalMouseMove = (e: MouseEvent) => {
      if (isDraggingStepCount.current) handleStepCountInteraction(e.clientX);
      if (isDraggingMs.current) handleMsDrag(e.clientY);
    };
    const handleGlobalMouseUp = () => {
      isDraggingStepCount.current = false;
      isDraggingMs.current = false;
      document.body.style.cursor = 'default';
    };

    window.addEventListener('mousemove', handleGlobalMouseMove);
    window.addEventListener('mouseup', handleGlobalMouseUp);
    return () => {
      window.removeEventListener('mousemove', handleGlobalMouseMove);
      window.removeEventListener('mouseup', handleGlobalMouseUp);
    };
  }, [handleMsDrag]);

  const isMsMode = state.syncDivision === 'ms';

  const DelayRadioButton: React.FC<{ division: string; label?: string; isFirstInRow?: boolean; isFirstRow?: boolean }> = ({ division, label, isFirstInRow, isFirstRow }) => {
    const isActive = state.syncDivision === division;
    return (
      <button
        onClick={() => state.isEnabled && setState(p => ({ ...p, syncDivision: division }))}
        className={`flex-1 h-9 border border-[#00ff41]/40 text-[11px] font-bold transition-all flex items-center justify-center cursor-pointer bg-[#121212] ${isFirstInRow ? '' : '-ml-[1px]'} ${isFirstRow ? '' : '-mt-[1px]'} ${
          isActive 
            ? 'bg-[#00ff41] text-black shadow-[0_0_15px_#00ff41aa] border-[#00ff41] z-10' 
            : 'text-[#00ff41] hover:bg-[#00ff41]/10 hover:z-10'
        }`}
      >
        {label || division}
      </button>
    );
  };

  return (
    <div className="flex flex-col min-h-screen items-center justify-center p-4 bg-[#050505]">
      {isExporterOpen && <CodeExporter onClose={() => setIsExporterOpen(false)} />}

      <div className="mb-4">
        <button 
          onClick={() => setIsExporterOpen(true)}
          className="px-6 py-2 border border-[#00ff41]/40 text-[#00ff41] text-[10px] font-bold uppercase tracking-widest hover:bg-[#00ff41] hover:text-black transition-all cursor-pointer shadow-[0_0_10px_rgba(0,255,65,0.1)]"
        >
          Export C++ Files (JUCE)
        </button>
      </div>

      <div className={`w-full max-w-[1040px] h-fit bg-[#121212] crt-border p-8 flex flex-col gap-4 overflow-hidden relative transition-opacity duration-500 ${!state.isEnabled ? 'opacity-40 grayscale-[0.5]' : 'opacity-100'}`}>

        <div className="flex justify-between items-center border-b border-green-500/20 pb-6">
          <div className="flex items-center gap-8">
            <div className="flex flex-col items-center gap-2">
               <span className="text-[9px] uppercase font-bold tracking-widest opacity-60">Power</span>
               <button 
                onClick={() => setState(p => ({ ...p, isEnabled: !p.isEnabled }))}
                className={`w-12 h-12 rounded-full border-2 flex items-center justify-center transition-all ${state.isEnabled ? 'bg-[#00ff41] border-[#00ff41] text-black shadow-[0_0_15px_#00ff41aa]' : 'bg-transparent border-[#00ff41]/20 text-[#00ff41]/20'}`}
               >
                 <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M18.36 6.64a9 9 0 1 1-12.73 0" />
                    <line x1="12" y1="2" x2="12" y2="12" />
                 </svg>
               </button>
            </div>

            <div className="flex flex-col justify-center">
              <h1 className="text-[4.125rem] font-black tracking-tighter crt-glow leading-[0.85]">AETHER</h1>
              <div className="mt-2 flex flex-col">
                <p className="text-[13px] uppercase tracking-widest text-[#00ff41] opacity-60">Polyphonic MIDI Delay</p>
                <p className="text-[12px] uppercase tracking-widest text-[#00ff41] opacity-60 mt-0.5">by darkInteger</p>
              </div>
            </div>
          </div>

          <div className="flex gap-10 items-start h-full pt-4">
            <div className="flex flex-col gap-0 min-w-[380px]">
              <div className="flex justify-between items-center mb-2">
                <span className="text-[10px] uppercase font-bold opacity-60 tracking-wider">DELAY TIME MATRIX</span>
              </div>

              <div className="flex gap-0">
                {SYNC_STRAIGHT.map((div, i) => <DelayRadioButton key={div} division={div} isFirstInRow={i === 0} isFirstRow />)}
              </div>
              <div className="flex gap-0">
                {SYNC_DOTTED.map((div, i) => <DelayRadioButton key={div} division={div} isFirstInRow={i === 0} />)}
              </div>
              <div className="flex gap-0">
                {SYNC_TRIPLET.map((div, i) => <DelayRadioButton key={div} division={div} isFirstInRow={i === 0} />)}
              </div>

              <div className="flex items-stretch -mt-[1px] h-9 gap-0">
                <button 
                  onClick={() => setState(p => ({ ...p, killOnStop: !p.killOnStop }))}
                  className={`flex-[2] border border-[#00ff41]/40 text-[9px] font-bold transition-all flex items-center justify-center tracking-tighter ${state.killOnStop ? 'bg-[#00ff41] text-black border-[#00ff41] z-10' : 'bg-[#121212] text-[#00ff41] hover:bg-[#00ff41]/10 hover:z-10'}`}
                >
                  KILL ON STOP
                </button>

                <button
                  onClick={() => state.isEnabled && setState(p => ({ ...p, syncDivision: 'ms' }))}
                  className={`flex-[3] border border-[#00ff41]/40 -ml-[1px] text-[10px] font-black uppercase tracking-widest transition-all ${
                    isMsMode 
                      ? 'bg-[#00ff41] text-black shadow-[0_0_15px_#00ff41aa] border-[#00ff41] z-10' 
                      : 'bg-[#121212] text-[#00ff41] hover:bg-[#00ff41]/10 hover:z-10'
                  }`}
                >
                  MANUAL (MS)
                </button>

                <div className={`flex-[1] flex flex-col items-stretch transition-all duration-300 ${!isMsMode ? 'opacity-20 grayscale' : 'opacity-100'}`}>
                  <div 
                    onMouseDown={onMsMouseDown}
                    className={`h-full bg-[#1a1a1a] border border-[#00ff41]/40 -ml-[1px] flex items-center justify-center transition-colors group select-none relative overflow-hidden ${isMsMode ? 'cursor-ns-resize hover:bg-[#00ff41]/5 border-[#00ff41]' : 'cursor-default'}`}
                  >
                    <span className="text-[14px] font-black text-[#00ff41] crt-glow">{Math.round(state.delayTimeMs)}</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className={`flex flex-col gap-4 transition-all duration-300 ${!state.isEnabled ? 'pointer-events-none' : ''}`}>
          <StepLane 
            label="Pitch Shift" 
            property="pitch" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={-24} max={24} 
            isBipolar 
            onUpdate={(i, v) => updateStep(i, v, 'pitch')}
            onRandomize={() => randomizeLane('pitch', -24, 24)}
            onReset={() => resetLane('pitch')}
          />
          <StepLane 
            label="Velocity" 
            property="velocity" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={1} max={127} 
            onUpdate={(i, v) => updateStep(i, v, 'velocity')}
            onRandomize={() => randomizeLane('velocity', 1, 127)}
            onReset={() => resetLane('velocity')}
          />
          <StepLane 
            label="Modwheel" 
            property="modwheel" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={127} 
            onUpdate={(i, v) => updateStep(i, v, 'modwheel')}
            onRandomize={() => randomizeLane('modwheel', 0, 127)}
            onReset={() => resetLane('modwheel')}
          />
          <StepLane 
            label="Probability" 
            property="probability" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={100} 
            onUpdate={(i, v) => updateStep(i, v, 'probability')}
            onRandomize={() => randomizeLane('probability', 0, 100)}
            onReset={() => resetLane('probability')}
          />
          <StepLane 
            label="Mute" 
            property="muted" 
            steps={state.steps} 
            stepCount={state.stepCount}
            min={0} max={1} 
            onUpdate={(i, v) => updateStep(i, v, 'muted')}
            onRandomize={() => randomizeLane('muted', 0, 1)}
            onReset={() => resetLane('muted')}
          />

          <div className="flex flex-col gap-1 mt-4 pb-2">
            <div className="flex justify-between items-end px-1">
              <span className="text-[12px] font-bold text-[#00ff41] crt-glow uppercase tracking-widest opacity-90">STEP COUNT: {state.stepCount}</span>
            </div>
            <div 
              ref={stepCountRef}
              onMouseDown={onStepCountMouseDown}
              className="h-6 bg-[#1a1a1a] border border-[#333] flex items-stretch gap-[2px] p-[2px] cursor-pointer relative"
            >
              {Array.from({ length: 15 }).map((_, i) => (
                <div 
                  key={i} 
                  className={`flex-1 transition-colors ${i < state.stepCount ? 'bg-[#00ff41]' : 'bg-green-900/10'}`}
                >
                  <div className={`h-full w-full ${i < state.stepCount ? 'shadow-[0_0_5px_#00ff4155]' : ''}`}></div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

